      'show-more-jutsu':()=>{ui.jutsuShow+=60;render();},'show-more-mission':()=>{ui.missionShow+=45;render();},'equip-weapon':()=>{state.equipment.weapon=id;saveState(true);render();},'equip-armor':()=>{state.equipment.armor=state.equipment.armor===id?null:id;recalc(state.character,false);saveState(true);render();},'check-ai':checkAIStatus,'ai-custom':aiCustom,'ai-generate-mission':aiGenerateMission,'apply-ai-effects':applyAIEffects,'ai-check':performAICheck,'cloud-save':()=>cloudSave(),'cloud-load':cloudLoad,'cloud-load-code':()=>cloudLoadById($('#online-player-id')?.value.trim()),'ai-choice':()=>{const text=t.dataset.text||t.textContent;$('#ai-prompt')&&($('#ai-prompt').value=text);aiCustom();},'encyclopedia-tab':()=>{ui.encyclopedia=id;render();},'export':exportSave,'close-modal':closeModal
