    const side=$('.map-side',screen);if(side){side.insertAdjacentHTML('afterbegin',`<div class="card event-list-card"><div class="card-header"><div><h3>Eventos no mapa</h3><p>Marcadores ativos agora.</p></div><span class="badge">${events.length}</span></div><div class="event-mini-list">${events.map(e=>`<button data-action="event-open" data-id="${e.id}"><img src="${esc(e.art)}"><span><b>${esc(e.nome)}</b><small>${esc(e.tipo)} • ${esc(e.npc)}</small></span></button>`).join('')||'<p class="muted">Nenhum evento ativo nesta vila hoje.</p>'}</div></div>`);if(ui.eventId){const e=eventByIdV74(ui.eventId);if(e)side.insertAdjacentHTML('afterbegin',eventPanelV74(e));}}
