  const renderShopV73=renderShop;
  renderShop=function(){
    ensureV74State();const c=state.character,village=state.travel?.currentVillage||c.village||'folha',vendors=(V7.vendors||[]).filter(v=>(v.vilas||[]).includes(village));const vendor=vendors.find(v=>v.id===ui.shopVendor)||vendors[0]||V7.vendors?.[0];if(vendor)ui.shopVendor=vendor.id;
    let buyItems=allItems().filter(i=>vendor?.categorias?.includes(itemCategory(i))).filter(i=>shopItemAllowed(i,c));const cats=['todos',...new Set(buyItems.map(itemCategory))];if(ui.shopCategory!=='todos')buyItems=buyItems.filter(i=>itemCategory(i)===ui.shopCategory);
    const sellItems=Object.entries(state.inventory||{}).filter(([,q])=>q>0).map(([id,q])=>[itemById(id),q]).filter(([i])=>i&&!i.unique);
    const buyCard=i=>{const qty=Math.max(1,Number(ui.shopQty[i.id]||1)),price=itemPrice(i,c),total=price*qty,art=v7ItemArt(i);return `<article class="shop-card-v74"><img src="${esc(art)}" alt="${esc(i.nome)}"><div class="shop-card-body"><div><span class="badge">${esc(itemCategory(i))}</span><span class="badge">${esc(itemRarity(i).toUpperCase())}</span></div><h3>${esc(i.nome)}</h3><p>${esc(itemDescription(i))}</p><div class="price-v74"><b>${fmt(price)} Ryos</b><small>por unidade</small></div><div class="qty-buy"><button data-action="shop-qty" data-id="${i.id}" data-delta="-1">−</button><b>${qty}</b><button data-action="shop-qty" data-id="${i.id}" data-delta="1">+</button><button class="btn" data-action="shop-buy-qty" data-id="${i.id}" ${c.ryo<total?'disabled':''}>Comprar ${qty} • ${fmt(total)}</button></div><small class="muted">${esc(i.fonte||'')}</small></div></article>`;};
    const sellCard=([i,q])=>{const qty=Math.min(q,Math.max(1,Number(ui.shopQty[i.id]||1))),unit=salePrice(i);return `<article class="shop-card-v74"><img src="${esc(v7ItemArt(i))}"><div class="shop-card-body"><h3>${esc(i.nome)} <small>×${q}</small></h3><p>${esc(itemDescription(i))}</p><div class="price-v74"><b>${fmt(unit)} Ryos</b><small>por unidade</small></div><div class="qty-buy"><button data-action="shop-qty" data-id="${i.id}" data-delta="-1">−</button><b>${qty}</b><button data-action="shop-qty" data-id="${i.id}" data-delta="1">+</button><button class="btn" data-action="shop-sell-qty" data-id="${i.id}">Vender ${qty} • ${fmt(unit*qty)}</button></div></div></article>`;};
    screen.innerHTML=`<div class="section-title compact-title"><div><span class="eyebrow">COMÉRCIO DA VILA</span><h1>Loja</h1><p>Estoque separado do inventário, imagens, preço unitário e compra/venda por quantidade.</p></div><span class="resource-pill big-money">💰 <b>${fmt(c.ryo)}</b> Ryos</span></div><div class="shop-layout-v74"><main><div class="shop-topline"><div class="vendor-tabs">${vendors.map(v=>`<button class="btn ${ui.shopVendor===v.id?'':'btn-secondary'}" data-action="shop-vendor" data-id="${v.id}">${esc(v.nome)}</button>`).join('')}</div><div class="shop-mode"><button class="btn ${ui.shopMode==='comprar'?'':'btn-secondary'}" data-action="shop-mode" data-id="comprar">Comprar</button><button class="btn ${ui.shopMode==='vender'?'':'btn-secondary'}" data-action="shop-mode" data-id="vender">Vender</button></div></div>${ui.shopMode==='comprar'?`<div class="category-tabs compact-tabs">${cats.map(x=>`<button class="btn ${ui.shopCategory===x?'':'btn-secondary'}" data-action="shop-category" data-id="${esc(x)}">${x==='todos'?'Tudo':esc(x)}</button>`).join('')}</div><div class="shop-grid-v74">${buyItems.map(buyCard).join('')||'<div class="card">Sem estoque.</div>'}</div>`:`<div class="shop-grid-v74">${sellItems.map(sellCard).join('')||'<div class="card">Nenhum item vendável.</div>'}</div>`}</main><aside class="shop-side-v74"><div class="card"><h3>${esc(vendor?.nome||'Loja')}</h3><p>Clique em +/− para definir exatamente quantas unidades comprar ou vender.</p></div><div class="card"><h3>Itens únicos</h3><p>Itens únicos e relíquias de evento não aparecem no estoque comum. Eles vêm de drops, quests e eventos do mapa.</p></div><button class="btn btn-secondary" data-screen="inventario">Abrir Inventário</button></aside></div>`;
  };
  function buyQtyV74(id){const i=itemById(id),c=state.character,qty=Math.max(1,Number(ui.shopQty[id]||1));if(!i||!shopItemAllowed(i,c))return toast('Item indisponível.','error');const total=itemPrice(i,c)*qty;if(c.ryo<total)return toast('Ryos insuficientes.','error');const cap=inventoryCompartments(),extra=Number(i.comp||0)*qty;if(!i.capacity&&cap.used+extra>cap.cap)return toast(`Sem espaço: ${cap.used}/${cap.cap} compartimentos usados.`,'error');c.ryo-=total;state.inventory[id]=(state.inventory[id]||0)+qty;saveState(true);toast(`${qty} × ${i.nome} comprado(s) por ${total} Ryos.`,'success');render();}
  function sellQtyV74(id){const i=itemById(id),have=Number(state.inventory[id]||0),qty=Math.min(have,Math.max(1,Number(ui.shopQty[id]||1)));if(!i||qty<=0||i.unique)return toast('Item não vendável.','error');if(state.equipment.weapon===id&&qty>=have)state.equipment.weapon=null;if(state.equipment.armor===id&&qty>=have)state.equipment.armor=null;const total=salePrice(i)*qty;state.inventory[id]=have-qty;state.character.ryo+=total;saveState(true);toast(`${qty} × ${i.nome} vendido(s) por ${total} Ryos.`,'success');render();}

  const renderInventoryV73=renderInventory;
