  const renderInventoryPre75=renderInventory;
  renderInventory=function(){ensureV75State();renderInventoryPre75();const c=state.character;if(c?.privateCharacter!=='leon')return;const k=V75.leon?.kurai?.ficha,tech=V75.leon?.kurai?.tecnicas||[];screen.insertAdjacentHTML('afterbegin',`<section class="card kurai-interactive-v75"><div class="kurai-hero"><img src="assets/rpg_v75/kurai_v75.svg"><div><span class="eyebrow">ITEM ÚNICO • ARMA VIVA</span><h2>Kurai</h2><p>${esc(k?.descricaoObjetiva||'')}</p><div class="resource-inline"><span>PV <b>${c.kurai.pv}/${c.kurai.maxPv}</b></span><span>Defesa <b>${k?.ficha?.Defesa||13}</b></span><span>Chakra <b>${c.kurai.chakra}/${c.kurai.maxChakra}</b></span><span>Dano <b>${k?.ficha?.danoBasico||2}</b></span></div></div></div><div class="button-row"><button class="btn ${c.kurai.mode==='empunhada'?'btn-success':'btn-secondary'}" data-action="kurai-mode" data-id="empunhada">Empunhar</button><button class="btn ${c.kurai.mode==='guardada'?'btn-success':'btn-secondary'}" data-action="kurai-mode" data-id="guardada">Guardar</button><label class="toggle-row compact"><input type="checkbox" id="kurai-share" ${ui.kuraiShare?'checked':''}><span>Partilha do Núcleo Espacial automática quando elegível</span></label></div><div class="kurai-actions-grid">${tech.map(t=>{const a=v75Action(`kurai:${t.id}`);return a?v75ActionCard(a):''}).join('')}</div></section>`);};

  const renderCreatePre75=renderCreate;
  renderCreate=function(){
    renderCreatePre75();const d=getCreationDraft(),steps=V5.creationSteps||[];const shell=$('.creation-shell',screen);if(!shell)return;
    const maxUnlocked=(()=>{let m=0;for(let i=0;i<steps.length-1;i++){if(validateCreationStep(i))break;m=i+1;}return Math.max(m,d.step);})();
    const nav=`<div class="creation-nav-v75 v76">${steps.map(([id,label],i)=>`<button data-action="creation-jump" data-id="${i}" class="${i===d.step?'active':''}" ${i>maxUnlocked?'disabled':''}><span>${i+1}</span>${esc(label)}</button>`).join('')}</div>`;shell.insertAdjacentHTML('afterbegin',nav);
    const bonus=originBonusObject(d.origin,d.hijutsu,d.ruleMode==='adapted');
    const pickedItems=Object.entries(d.equipment||{}).filter(([,q])=>Number(q)>0).map(([id,q])=>`${itemById(id)?.nome||id} ×${q}`).slice(0,5);
    const powers=Object.entries(d.powers||{}).filter(([,v])=>Number(v)>0).map(([id,v])=>`${powerById(id)?.nome||id} ${v}`).slice(0,5);
    const preview=`<aside class="creation-live-v75 v76"><div class="card"><span class="eyebrow">FICHA EM MONTAGEM • AINDA NÃO CRIADA</span><div class="creation-mini-head"><img src="${esc(d.identity.avatar||'assets/ui/avatar.png')}"><div><h3>${esc(d.identity.name||'Novo Shinobi')}</h3><small>${esc(LIV.vilas?.[d.identity.village]?.curto||'Vila')} • ${esc(originById(d.origin)?.nome||'Sem Clã')}${d.hijutsu?` • ${esc(hijutsuById(d.hijutsu)?.nome||'')}`:''}</small></div></div><div class="summary-grid mini"><div><b>${creationAttrSpent(d)}/12</b><small>Atributos</small></div><div><b>${creationSkillSpent(d)}/8</b><small>Perícias</small></div><div><b>${d.aptitudes.length}/3</b><small>Aptidões</small></div><div><b>${creationPowerSpent(d)}/4</b><small>PP</small></div></div><h4>Escolhas atuais</h4><div class="creation-choice-list-v76"><span><b>Estilo:</b> ${esc(LIV.classes?.[d.class]?.nome||'—')}</span><span><b>Elemento:</b> ${esc(LIV.elementos?.[d.element]?.nome||'—')}</span><span><b>Ofício:</b> ${esc(professionById(d.profession)?.nome||'—')}</span><span><b>Poderes:</b> ${esc(powers.join(' • ')||'nenhum')}</span><span><b>Equipamentos:</b> ${esc(pickedItems.join(' • ')||'nenhum')}</span></div><h4>Atributos finais previstos</h4><div class="rpg-stat-grid">${coreAttrKeys().map(k=>`<div><span>${esc(attrNames[k])}</span><b>${Number(d.attributes[k]||0)+Number(bonus[k]||0)}</b></div>`).join('')}</div><div class="notice mini">Você pode voltar às etapas e mudar as escolhas. <b>Nenhum personagem/save é criado antes do botão final da Revisão.</b></div></div></aside>`;shell.insertAdjacentHTML('beforeend',preview);
  };

  const renderChromePre75=renderChrome;
  renderChrome=function(){ensureV75State();renderChromePre75();const c=state.character;if(!c)return;if(c.privateCharacter==='leon')topResources.innerHTML=`<span class="resource-pill live hp">❤️ <b>${c.hp}/${c.maxHp}</b></span><span class="resource-pill live chakra">🔵 <b>${c.chakra}/${c.maxChakra}</b></span><span class="resource-pill live kurai">🗡️ Kurai <b>${c.kurai?.chakra??0}/${c.kurai?.maxChakra??8}</b> • ${c.kurai?.mode==='empunhada'?'Empunhada':'Guardada'}</span><span class="resource-pill live kusenro">🌌 Kūsenrō <b>${c.kusenroChakra??0}/${c.kusenroMaxChakra??6}</b></span>`;else topResources.innerHTML=`<span class="resource-pill live hp">❤️ <b>${c.hp}/${c.maxHp}</b></span><span class="resource-pill live chakra">🔵 <b>${c.chakra}/${c.maxChakra}</b></span><span class="resource-pill live stamina">🟢 <b>${c.stamina}/${c.maxStamina}</b></span>${state.equipment?.weapon?`<span class="resource-pill live weapon">⚔️ <b>${esc(itemById(state.equipment.weapon)?.nome||'Arma')}</b></span>`:''}`;};

  const aiGameContextPre75=aiGameContext;
  aiGameContext=function(){ensureV75State();const b=aiGameContextPre75();b.rpg={lastAction:state.rpgActionLog.slice(-1)[0]||null,recentActions:state.rpgActionLog.slice(-10),availableActions:v75Actions().slice(0,400).map(a=>({id:a.id,name:a.name,group:a.group,activation:a.activation,cost:a.cost,range:a.range,target:a.target,description:a.description,limit:a.limit||''})),inventory:Object.entries(state.inventory||{}).filter(([,q])=>Number(q)>0).map(([id,q])=>({id,name:itemById(id)?.nome||id,qty:q,description:itemDescription(itemById(id)||{})})),equipment:{...state.equipment,weaponName:itemById(state.equipment?.weapon)?.nome||'',armorName:itemById(state.equipment?.armor)?.nome||''},rinnegan:state.character?.hijutsu==='rinnegan'?{paths:state.specialProgress.rinneganPaths,nature:state.specialProgress.rinneNature}:null,kurai:state.character?.privateCharacter==='leon'?state.character.kurai:null,kusenroChakra:state.character?.privateCharacter==='leon'?state.character.kusenroChakra:null};return b;};

  // Immediate persistence after any tactical jutsu resource payment.
  const useBattleJutsuPre75=useBattleJutsu;
  useBattleJutsu=function(id){const before=state.character?{chakra:state.character.chakra,stamina:state.character.stamina}:null;useBattleJutsuPre75(id);if(before&&state.character&&(state.character.chakra!==before.chakra||state.character.stamina!==before.stamina)){saveState(true);renderChrome();}};

  document.addEventListener('input',e=>{if(e.target?.id==='rpg-search'){ui.rpgSearch=e.target.value;const pos=e.target.selectionStart;render();const n=$('#rpg-search');if(n){n.focus();try{n.setSelectionRange(pos,pos);}catch{}}}if(e.target?.id==='rpg-roll-cd')ui.rpgRollDifficulty=Number(e.target.value||12);if(e.target?.id==='kurai-share')ui.kuraiShare=!!e.target.checked;});
  document.addEventListener('click',async e=>{
    const t=e.target?.closest?.('[data-action]');if(!t)return;const act=t.dataset.action,id=t.dataset.id||'';
    if(act==='rpg-tab'){ui.rpgTab=id;render();return;}
    if(act==='rpg-select'){ui.rpgSelected=ui.rpgSelected===id?'':id;render();return;}
    if(act==='rpg-use'){const a=v75Action(id);if(a?.passive){ui.rpgSelected=id;render();return;}await useRpgActionV75(id);return;}
    if(act==='rpg-confirm-cost'){const a=v75Action(id),choice={confirmed:true,costOption:$('#v75-cost-option')?.value||'',option:$('#v75-action-option')?.value||'',variableCost:Number($('#v75-variable-cost')?.value||0),kuraiPay:Number($('#v75-kurai-pay')?.value||0),quantity:Number($('#v75-clone-qty')?.value||0),extra:($('#v76-action-text')?.value||'').trim()};closeModal();await useRpgActionV75(id,choice);return;}
    if(act==='rpg-roll'){rpgRollV75(id);return;}
    if(act==='rpg-continue'){const result=await callAI({mode:'game_master',prompt:'Continue a cena a partir do último estado. Não decida a ação do personagem pelo jogador; apresente a situação e oportunidades.',state:aiGameContext(),history:ui.aiChat.slice(-12)});ui.aiDraft=result;const tx=result?.scene?.narrative||result?.narrativa||'';if(tx)ui.aiChat.push({role:'ai',text:tx});saveState(true);if(state.settings.aiStateChanges&&v75HasEffects())applyAIEffects({silent:true,noRender:true});renderChrome();render();return;}
    if(act==='rpg-option'){const opts=ui.aiDraft?.options||ui.aiDraft?.scene?.options||[];const opt=opts[Number(id)];if(opt){const text=opt.label||opt.text||String(opt);const input=$('#ai-prompt');if(input){input.value=text;input.focus();}}return;}
    if(act==='rpg-resource'){adjustRpgResourceV75(id);return;}
    if(act==='rinne-unlock'){unlockRinnePathV75(id);return;}
    if(act==='kurai-mode'){state.character.kurai.mode=id;if(state.masterV83?.active)state.masterV83.active.kuraiMode=id;saveState(true);render();return;}
    if(act==='creation-jump'){const target=Number(id),d=getCreationDraft();if(target>d.step){for(let i=0;i<target;i++){const err=validateCreationStep(i);if(err){d.step=i;writeCreationDraft();toast(err,'error',5000);render();return;}}}d.step=clamp(target,0,(V5.creationSteps||[]).length-1);writeCreationDraft();render();return;}
  });

  ensureV75State();


  let _privateChordCount=0,_privateChordTimer=0,_privateWord='',_privateWordTimer=0,_privateLogoClicks=0,_privateLogoTimer=0;
  function privateAccessAllowed(){
    return !state.character || ui.screen==='personagens';
  }
  document.addEventListener('keydown',e=>{
    if(!privateAccessAllowed())return;
    const tag=String(e.target?.tagName||'').toLowerCase();
    const typingTarget=['input','textarea','select'].includes(tag) || e.target?.isContentEditable;
    const now=Date.now();

    // Método 1: atalho forte, mantido por compatibilidade.
    if(e.ctrlKey&&e.altKey&&e.shiftKey&&String(e.key).toLowerCase()==='l'){
      e.preventDefault();
      if(now-_privateChordTimer>5000)_privateChordCount=0;
      _privateChordTimer=now;_privateChordCount++;
      if(_privateChordCount>=3){_privateChordCount=0;_privateWord='';leonUnlock();}
      return;
    }

    // Método 2: palavra secreta sem elemento visível na interface.
    if(!typingTarget && !e.ctrlKey && !e.altKey && !e.metaKey && /^[a-zA-Z]$/.test(String(e.key))){
      if(now-_privateWordTimer>4500)_privateWord='';
      _privateWordTimer=now;
      _privateWord=(_privateWord+String(e.key).toUpperCase()).slice(-12);
      if(_privateWord.endsWith('KOSMO')){
        _privateWord='';
        leonUnlock();
      }
    }
  });

  // Método 3: gesto oculto no logotipo. Não cria botão nem texto.
  document.addEventListener('click',e=>{
    if(!privateAccessAllowed())return;
    const brand=e.target?.closest?.('.brand');
    if(!brand)return;
    const now=Date.now();
    if(now-_privateLogoTimer>4000)_privateLogoClicks=0;
    _privateLogoTimer=now;_privateLogoClicks++;
    if(_privateLogoClicks>=7){
      _privateLogoClicks=0;
      leonUnlock();
    }
  });

  

