function v8EnsureCreationVisuals(d=getCreationDraft()){
  d.identity=d.identity||{};
  d.identity.visuals={hair:'Curto espetado',face:'Rosto jovem',eyes:'Olhos castanhos',outfit:'Traje de vila padrão',...(d.identity.visuals||{})};
  d.identity.visualSummary=d.identity.visualSummary||'';
  return d.identity.visuals;
}
function v8VisualSummary(d=getCreationDraft()){
  const v=v8EnsureCreationVisuals(d);
  return `Cabelo: ${v.hair} • Rosto: ${v.face} • Olhos: ${v.eyes} • Roupa: ${v.outfit}`;
}
function v8ChoiceButtons(kind,list,selected){
  return `<div class="v8-choice-buttons">${list.map(name=>`<button class="v8-choice-pill ${selected===name?'selected':''}" data-action="v8-visual" data-kind="${kind}" data-id="${esc(name)}">${esc(name)}</button>`).join('')}</div>`;
}
function v8ProgressHtml(c=state.character){
  if(!c)return '';
  const need=Math.max(1,Number(xpNeeded(c.level)||1));
  const current=Math.max(0,Number(c.xp||0));
  const percent=Math.max(0,Math.min(100,Math.round(current/need*100)));
  const rows=[];
  for(let lv=c.level;lv<Math.min(MAX_LEVEL,c.level+5);lv++){
    rows.push(`<div class="v8-xp-row"><b>Nv ${lv}</b><span>${xpNeeded(lv)} XP</span><small>+2 perícia${lv%2===1?' • +1 atributo no próximo':''}${lv%3===2?' • +1 aptidão no próximo':''}</small></div>`);
  }
  return `<section class="v8-progress-card"><div class="v8-progress-head"><div><span class="eyebrow">PROGRESSÃO</span><h3>Nível ${c.level} • ${esc(c.graduation||'')}</h3></div><small>${current}/${need} XP</small></div><div class="v8-xp-bar"><span style="width:${percent}%"></span></div><div class="v8-xp-mini">Faltam <b>${Math.max(0,need-current)}</b> XP para o próximo nível.</div><div class="v8-xp-table">${rows.join('')}</div></section>`;
}

const renderCreateV8Base=renderCreate;
renderCreate=function(){
  renderCreateV8Base();
  const d=getCreationDraft();
  v8EnsureCreationVisuals(d);
  const shell=$('.creation-shell',screen);
  if(!shell)return;
  const previewCard=shell.querySelector('.creation-live-v75 .card');
  if(previewCard&&!previewCard.querySelector('.v8-appearance-preview')){
    previewCard.insertAdjacentHTML('beforeend',`<div class="v8-appearance-preview"><h4>Visual montado</h4><div class="v8-appearance-summary">${esc(v8VisualSummary(d))}</div><div class="v8-preview-images"><img src="${V8_UI_ASSETS.roster}" alt="classes"><img src="${V8_UI_ASSETS.outfit}" alt="trajes"></div></div>`);
  }
  if(d.step!==0)return;
  const grid=shell.querySelector('.wizard-grid');
  if(!grid||grid.querySelector('.v8-visual-card'))return;
  grid.insertAdjacentHTML('beforeend',`<div class="card v8-visual-card"><div class="v8-visual-head"><div><h2>Montagem visual do shinobi</h2><p>Escolha cabelo, rosto, olhos e traje. O resumo visual fica salvo na ficha em montagem.</p></div><img src="${V8_UI_ASSETS.roster}" alt="roster"></div><div class="v8-visual-inspo"><img src="${V8_UI_ASSETS.hair}" alt="cabelos"><img src="${V8_UI_ASSETS.outfit}" alt="trajes"></div><div class="v8-choice-group"><label>Cabelo</label>${v8ChoiceButtons('hair',V8_HAIR,d.identity.visuals.hair)}</div><div class="v8-choice-group"><label>Rosto</label>${v8ChoiceButtons('face',V8_FACE,d.identity.visuals.face)}</div><div class="v8-choice-group"><label>Olhos</label>${v8ChoiceButtons('eyes',V8_EYES,d.identity.visuals.eyes)}</div><div class="v8-choice-group"><label>Roupa</label>${v8ChoiceButtons('outfit',V8_OUTFITS,d.identity.visuals.outfit)}</div><div class="notice mini">Dica: use o campo <b>Aparência</b> para adicionar altura, cicatrizes, acessórios ou detalhes extras.</div></div>`);
  const appearance=$('#create-appearance');
  if(appearance && !appearance.value.trim()) appearance.value=v8VisualSummary(d);
};

const renderCharacterV8Base=renderCharacter;
renderCharacter=function(){
  renderCharacterV8Base();
  const c=state.character;if(!c)return;
  if(c.privateCharacter==='leon'){
    const host=screen.querySelector('.section-title')||screen.firstElementChild;
    if(host && !screen.querySelector('.v8-progress-card')) host.insertAdjacentHTML('afterend',v8ProgressHtml(c));
    return;
  }
  const headerGrid=screen.querySelector('.grid.grid-4');
  if(headerGrid && !screen.querySelector('.v8-progress-card')) headerGrid.insertAdjacentHTML('afterend',v8ProgressHtml(c));
};

const v75SheetPanelV8Base=v75SheetPanel;
v75SheetPanel=function(c){
  let html=v75SheetPanelV8Base(c);
  if(!html||!c)return html;
  const need=Math.max(1,Number(xpNeeded(c.level)||1));
  const current=Math.max(0,Number(c.xp||0));
  const percent=Math.max(0,Math.min(100,Math.round(current/need*100)));
  const block=`<div class="v8-sheet-progress"><div class="progress-label"><span>XP • Nível ${c.level}</span><span>${current}/${need}</span></div><div class="bar xp"><span style="width:${percent}%"></span></div><small class="muted">${Math.max(0,need-current)} XP para o próximo nível</small></div>`;
  return html.replace('</div></aside>',`${block}</div></aside>`).replace('</div>`;','');
};

