document.addEventListener('click',e=>{
  const t=e.target?.closest?.('[data-action]');
  if(!t)return;
  const act=t.dataset.action,id=t.dataset.id||'',kind=t.dataset.kind||'';
  if(act==='v8-visual'){
    const d=getCreationDraft();
    v8EnsureCreationVisuals(d);
    d.identity.visuals[kind]=id;
    d.identity.visualSummary=v8VisualSummary(d);
    writeCreationDraft();
    render();
    return;
  }
  if(act==='dojo-duel'){
    startBattle(id==='elite'?'elite':null);
    return;
  }
  if(act==='v8-open-ai-train'){
    ui.screen='mestre-ia';
    render();
    return;
  }
  if(act==='leon-dojo'){
    modal('Treino guiado por IA', `<p>O duelo simplificado de 3 trocas foi descontinuado nesta edição. Para Leon, o treino agora deve seguir pela <b>Mesa do Mestre IA</b>, usando a ficha viva, gasto de recursos e narração no mesmo fluxo.</p><p>Abra a Mesa do Mestre IA para escolher ações, técnicas, dojutsu, itens e descrição narrativa.</p>`, `<button class="btn" data-action="v8-open-ai-train">Abrir Mestre IA</button><button class="btn btn-secondary" data-action="close-modal">Fechar</button>`);
    return;
  }
});


  

