function v8Asset(kind,index){return `assets/ui_v8/${kind}/${String(index).padStart(2,'0')}.jpg`;}
function v8CreatorAsset(kind,index){return `assets/ui_v8/creator/${kind}/${kind}_${String(index).padStart(2,'0')}.jpg`;}
function v8TechAsset(index){return `assets/ui_v8/techniques/cards/tech_${String(index).padStart(2,'0')}.jpg`;}
function v8ItemAsset(index){return `assets/ui_v8/items/cards/item_${String(index).padStart(2,'0')}.jpg`;}
function v8ActionAsset(index){return `assets/ui_v8/combat/actions/action_${String(index).padStart(2,'0')}.jpg`;}
function v8EventAsset(index){return `assets/ui_v8/events/cards/event_${String(index).padStart(2,'0')}.jpg`;}

const V8_VISUAL_INDEX={
  hair:Object.fromEntries(V8_HAIR.map((x,i)=>[x,i+1])),
  face:Object.fromEntries(V8_FACE.map((x,i)=>[x,i+1])),
  eyes:Object.fromEntries(V8_EYES.map((x,i)=>[x,Math.min(16,i+1)])),
  outfit:Object.fromEntries(V8_OUTFITS.map((x,i)=>[x,i+1]))
};
v8ChoiceButtons=function(kind,list,selected){
  const folder=kind==='outfit'?'outfit':kind==='hair'?'hair':'face';
  return `<div class="v8-visual-choice-grid">${list.map((name,i)=>{const idx=V8_VISUAL_INDEX[kind]?.[name]||i+1;return `<button class="v8-visual-tile ${selected===name?'selected':''}" data-action="v8-visual" data-kind="${kind}" data-id="${esc(name)}"><img src="${v8CreatorAsset(folder,idx)}" alt=""><span>${esc(name)}</span></button>`;}).join('')}</div>`;
};

const createCharacterV8FinalBase=createCharacter;
createCharacter=function(){
  const d=getCreationDraft();v8EnsureCreationVisuals(d);const choices={...d.identity.visuals};
  const visual=v8VisualSummary(d);if(!String(d.identity.appearance||'').includes('Cabelo:'))d.identity.appearance=[visual,d.identity.appearance].filter(Boolean).join(' • ');
  createCharacterV8FinalBase();
  if(state.character){state.character.appearanceChoices=choices;state.character.visualSummary=visual;saveState(true);}
};

const gainXpV8Base=gainXp;
gainXp=function(amount){
  const c=state.character;if(!c)return;amount=Math.max(0,Math.round(Number(amount)||0));if(!amount)return;
  if(c.privateCharacter!=='leon'){gainXpV8Base(amount);return;}
  c.xp=Number(c.xp||0)+amount;state.stats.totalXp=Number(state.stats.totalXp||0)+amount;let levels=0;
  while(c.level<MAX_LEVEL&&c.xp>=xpNeeded(c.level)){
    c.xp-=xpNeeded(c.level);c.level++;levels++;
    c.trainingPoints=Number(c.trainingPoints||0)+2;c.skillPoints=Number(c.skillPoints||0)+2;c.powerPoints=Number(c.powerPoints||0)+1;
    if(c.level%3===0)c.aptitudePoints=Number(c.aptitudePoints||0)+1;
  }
  if(levels){const g=graduationFor(c.level);c.nc=ncFor(c.level);if(g?.nome)c.graduation=g.nome;toast(`Leon avançou ${levels} nível(is). Agora: nível ${c.level} • ${c.graduation||'progressão atualizada'}.`,'success',6000);}
  saveState(true);
};

function v8XpTableRows(){return Array.from({length:MAX_LEVEL},(_,i)=>{const lv=i+1;return {level:lv,xp:lv<MAX_LEVEL?xpNeeded(lv):0,nc:ncFor(lv),graduation:graduationFor(lv)?.nome||''};});}
v8ProgressHtml=function(c=state.character){
  if(!c)return'';const need=c.level>=MAX_LEVEL?0:Math.max(1,Number(xpNeeded(c.level)||1)),current=Math.max(0,Number(c.xp||0)),percent=c.level>=MAX_LEVEL?100:Math.max(0,Math.min(100,Math.round(current/need*100)));
  const upcoming=v8XpTableRows().slice(Math.max(0,c.level-1),Math.min(MAX_LEVEL,c.level+4));
  return `<section class="v8-progress-card"><div class="v8-progress-head"><div><span class="eyebrow">PROGRESSÃO</span><h3>Nível ${c.level} • ${esc(c.graduation||graduationFor(c.level)?.nome||'')}</h3></div><small>${c.level>=MAX_LEVEL?'NÍVEL MÁXIMO':`${current}/${need} XP`}</small></div><div class="v8-xp-bar"><span style="width:${percent}%"></span></div><div class="v8-xp-mini">${c.level>=MAX_LEVEL?'Progressão máxima atingida.':`Faltam <b>${Math.max(0,need-current)}</b> XP para o próximo nível.`}</div><div class="v8-xp-table">${upcoming.map(x=>`<div class="v8-xp-row"><b>Nv ${x.level}</b><span>${x.level<MAX_LEVEL?`${x.xp} XP → próximo`:'Máximo'}</span><small>NC ${x.nc} • ${esc(x.graduation)}</small></div>`).join('')}</div><button class="btn btn-small btn-secondary" data-action="v8-xp-table">Ver tabela completa 1–${MAX_LEVEL}</button></section>`;
};

const applyAIEffectsV8Old=applyAIEffects;
applyAIEffects=function(options={}){
  const c=state.character,raw=ui.aiDraft?.effects||ui.aiDraft?.efeitos;if(!c||!raw)return false;
  if(!state.settings.aiStateChanges){if(!options.silent)toast('Alterações de estado pela IA estão desativadas.','error');return false;}
  const e={...raw,addConditions:[...(raw.addConditions||[])],removeConditions:[...(raw.removeConditions||[])]};if(options.skipPaidResources){e.chakra=0;e.stamina=0;}
  const safe={xp:clamp(Number(e.xp)||0,0,100),ryo:clamp(Number(e.ryo)||0,0,1000),hp:clamp(Number(e.hp)||0,-15,15),chakra:clamp(Number(e.chakra)||0,-10,10),stamina:clamp(Number(e.stamina)||0,-10,10),reputacao:clamp(Number(e.reputacao)||0,-2,3)};
  const before={level:c.level,xp:c.xp,hp:c.hp,chakra:c.chakra,stamina:c.stamina,ryo:c.ryo,rep:state.story.reputation};
  if(safe.xp)gainXp(safe.xp);c.ryo=Math.max(0,Number(c.ryo||0)+safe.ryo);c.hp=clamp(Number(c.hp||0)+safe.hp,c.privateCharacter==='leon'?0:-21,Number(c.maxHp||16));c.chakra=clamp(Number(c.chakra||0)+safe.chakra,0,Number(c.maxChakra||18));
  if(c.stamina!=null&&c.maxStamina!=null)c.stamina=clamp(Number(c.stamina||0)+safe.stamina,0,Number(c.maxStamina||0));state.story.reputation=Math.max(0,Number(state.story.reputation||0)+safe.reputacao);
  for(const cond of (e.addConditions||[]).slice(0,5))if(cond&&!c.conditions.includes(cond))c.conditions.push(cond);if(Array.isArray(e.removeConditions))c.conditions=c.conditions.filter(x=>!e.removeConditions.includes(x));
  const changed=Object.keys(before).some(k=>before[k]!==({level:c.level,xp:c.xp,hp:c.hp,chakra:c.chakra,stamina:c.stamina,ryo:c.ryo,rep:state.story.reputation})[k])||(e.addConditions||[]).length>0||(e.removeConditions||[]).length>0;
  ui.aiDraft.effects={xp:0,ryo:0,hp:0,chakra:0,stamina:0,reputacao:0,addConditions:[],removeConditions:[]};ui.aiDraft.efeitos=ui.aiDraft.effects;
  state.ai={...state.ai,history:ui.aiChat,lastDraft:ui.aiDraft,lastCheck:ui.aiLastCheck,director:currentAIDirector()};saveState(true);renderChrome();
  if(changed){ui.rpgLog=ui.rpgLog||[];ui.rpgLog.push({type:'effect',text:`Efeitos aplicados: ${safe.xp?`+${safe.xp} XP • `:''}${safe.ryo?`+${safe.ryo} Ryos • `:''}nível ${before.level}→${c.level}.`});ui.rpgLog=ui.rpgLog.slice(-40);}
  if(!options.noRender)render();if(changed&&!options.silent)toast('Efeitos da IA validados pelo motor e aplicados à ficha.','success');return changed;
};

const aiGameContextV8FinalBase=aiGameContext;
aiGameContext=function(){
  const x=aiGameContextV8FinalBase();const c=state.character;
  x.progression={level:c?.level||1,currentXp:c?.xp||0,nextLevelXp:c&&c.level<MAX_LEVEL?xpNeeded(c.level):0,maxLevel:MAX_LEVEL,graduation:c?.graduation||'',attributePoints:c?.attributePoints||0,skillPoints:c?.skillPoints||0,powerPoints:c?.powerPoints||0,aptitudePoints:c?.aptitudePoints||0,trainingPoints:c?.trainingPoints||0,xpTable:v8XpTableRows(),awardRules:'A IA sugere apenas XP/Ryos/reputação. Nunca altera nível diretamente. O motor processa todos os level-ups e pontos.'};
  return x;
};

function v8TechniqueFallback(j){const s=v75Norm(`${j?.name||''} ${j?.description||''} ${j?.element||''} ${j?.class||''}`);let n=6;if(/katon|fogo/.test(s))n=1;else if(/suiton|agua|água/.test(s))n=2;else if(/raiton|raio/.test(s))n=3;else if(/doton|terra/.test(s))n=4;else if(/fuuton|futon|vento/.test(s))n=5;else if(/clone/.test(s))n=6;else if(/transform/.test(s))n=7;else if(/genjutsu|ilus/.test(s))n=8;else if(/sharingan/.test(s))n=9;else if(/byakugan|hyuuga/.test(s))n=10;else if(/invoca|kuchiyose/.test(s))n=11;else if(/medic|cura|iryou/.test(s))n=12;else if(/kunai|shuriken/.test(s))n=13;else if(/explos/.test(s))n=14;else if(/kugutsu|marion/.test(s))n=15;else if(/selamento|fuuin/.test(s))n=16;else if(/taijutsu|chute|soco/.test(s))n=17;else if(/senjutsu|sabio|sábio/.test(s))n=18;else if(/rinne|grav/.test(s))n=19;else if(/kū|espacial|portal|fenda/.test(s))n=20;return v8TechAsset(n);}
function v8ItemFallback(i){const s=v75Norm(`${i?.id||''} ${i?.nome||''} ${i?.tipo||''} ${i?.efeito||''}`);let n=20;if(/kunai/.test(s))n=1;else if(/shuriken/.test(s))n=2;else if(/senbon/.test(s))n=3;else if(/explos/.test(s))n=4;else if(/fumaca|fumaça|smoke/.test(s))n=5;else if(/pilula|pílula/.test(s))n=6;else if(/bandage|bandagem|curativo/.test(s))n=7;else if(/antidoto|antídoto/.test(s))n=8;else if(/chakra.*perg|perg.*chakra/.test(s))n=9;else if(/arma.*perg|perg.*arma/.test(s))n=10;else if(/katana|espada/.test(s))n=11;else if(/fio|wire/.test(s))n=12;else if(/ramen/.test(s))n=13;else if(/bandana|headband/.test(s))n=14;else if(/armadura|colete/.test(s))n=15;else if(/kugutsu|marion/.test(s))n=16;else if(/contrato|invoca/.test(s))n=17;else if(/mapa/.test(s))n=18;else if(/lanterna|tocha/.test(s))n=19;return v8ItemAsset(n);}
const v7ItemArtV8FinalBase=v7ItemArt;
v7ItemArt=function(i){const old=v7ItemArtV8FinalBase(i);if(!old||/layout_topo_logado_icones_bag2|action\.svg/.test(old))return v8ItemFallback(i);return old;};
const v75ActionsV8ArtBase=v75Actions;
v75Actions=function(){return v75ActionsV8ArtBase().map(a=>{if(!a.art||/action\.svg|jutsu_nin\.svg/.test(a.art)){if(a.group==='item'||a.group==='weapon')a.art=v8ItemFallback(a.raw||{id:a.sourceId,nome:a.name});else if(a.group==='acao'){const m={basic_attack:1,defend:2,move:4};a.art=v8ActionAsset(m[String(a.sourceId||a.id).replace('action:','')]||6);}else a.art=v8TechniqueFallback(a.raw||{name:a.name,description:a.description});}return a;});};

// ---------- Combate privado TERION 2D10 ----------
function v8LeonTerrain(){const out=[];for(let y=0;y<5;y++)for(let x=0;x<7;x++)out.push({x,y,type:(x===3&&y===2)?'cover':'floor'});return out;}
function v8StartLeonBattle(elite=false){
  const c=state.character;if(!c||c.privateCharacter!=='leon')return;ensureLeonKuraiV74(c);const hard=elite===true||elite==='elite';
  const hp=hard?22:15;ui.battle={engine:'TERION_2D10',enemy:{name:hard?'Instrutor Jōnin TERION':'Shinobi de Treino',rank:hard?'B':'D',level:Math.max(1,Number(c.level||1)),maxHp:hp,hp,cd:hard?14:11,attackBonus:hard?4:2,damage:hard?4:2,conditions:[],art:hard?'assets/enemies_v7/elite_espachim.svg':'assets/enemies_v7/bandido_batedor.svg'},turn:1,playerPos:{x:1,y:2},enemyPos:{x:5,y:2},terrain:v8LeonTerrain(),moveUsed:false,guard:0,cooldowns:{},log:[{text:'Duelo TERION iniciado. Escolha movimento, ataque, defesa, técnica, dōjutsu, item ou fuga.',type:'info'}],over:false};ui.screen='combate';saveState(true);render();
}
function v8LeonSkillFor(a){const c=state.character,s=c?.specialProfile?.skillRatings||{},txt=v75Norm(`${a?.name||''} ${a?.description||''}`);if(a?.group==='weapon'||/kurai|kenjutsu|espada/.test(txt))return Number(s['Kenjutsu/Kurai']??s.Kenjutsu??4);if(a?.group==='dojutsu'||/espacial|portal|kū|rinne/.test(txt))return Number(s['Controle Espacial']??s.Ninjutsu??3);if(a?.group==='summon')return Number(s.Invocação??s.Invocacao??s.Ninjutsu??3);return Number(s.Ninjutsu??s.Taijutsu??3);}
function v8LeonDefenseCD(){const c=state.character,s=c?.specialProfile?.skillRatings||{};return 10+Number(s.Esquiva??s.Acrobatismo??s['Defesa']??2)+Number(ui.battle?.guard||0);}
function v8LeonLog(text,type='info'){if(!ui.battle)return;ui.battle.log.push({text,type});ui.battle.log=ui.battle.log.slice(-40);}
function v8LeonFinish(win){const b=ui.battle,c=state.character;if(!b||b.over)return;b.over=true;if(win){const xp=b.enemy.rank==='B'?90:45,ryo=b.enemy.rank==='B'?180:90;c.ryo=Number(c.ryo||0)+ryo;gainXp(xp);state.stats.wins=Number(state.stats.wins||0)+1;v8LeonLog(`VITÓRIA • +${xp} XP • +${ryo} Ryos.`,'good');toast('Vitória no duelo TERION.','success');}else{state.stats.losses=Number(state.stats.losses||0)+1;c.hp=Math.max(1,Number(c.hp||1));v8LeonLog('DERROTA • treino encerrado e Leon permanece com 1 PV.','bad');toast('Duelo encerrado.','error');}saveState(true);render();}
function v8LeonNextTurn(){const b=ui.battle;if(!b||b.over)return;b.turn++;b.moveUsed=false;b.guard=0;for(const k of Object.keys(b.cooldowns||{}))b.cooldowns[k]=Math.max(0,Number(b.cooldowns[k]||0)-1);saveState(true);render();}
function v8LeonEnemyTurn(){const b=ui.battle,c=state.character;if(!b||b.over)return;const dist=gridDistance(b.playerPos,b.enemyPos);if(dist>1){const dx=Math.sign(b.playerPos.x-b.enemyPos.x),dy=Math.sign(b.playerPos.y-b.enemyPos.y);b.enemyPos={x:clamp(b.enemyPos.x+dx,0,11),y:clamp(b.enemyPos.y+(Math.abs(dy)>0?dy:0),0,4)};v8LeonLog(`${b.enemy.name} se reposicionou. Distância agora ${gridDistance(b.playerPos,b.enemyPos)}.`,'info');v8LeonNextTurn();return;}const d=rollLeon2d10(),total=d.hope+d.doom+b.enemy.attackBonus,cd=v8LeonDefenseCD();if(total>=cd){c.hp=Math.max(0,Number(c.hp||0)-b.enemy.damage);v8LeonLog(`${b.enemy.name}: ${d.hope}+${d.doom}+${b.enemy.attackBonus}=${total} vs CD ${cd}; Leon sofre ${b.enemy.damage} PV.`,'bad');if(c.hp<=0){v8LeonFinish(false);return;}}else v8LeonLog(`${b.enemy.name}: ${d.hope}+${d.doom}+${b.enemy.attackBonus}=${total} vs CD ${cd}; ataque defendido.`,'good');v8LeonNextTurn();}
function v8LeonBasicAttack(){const b=ui.battle,c=state.character;if(!b||b.over)return;if(gridDistance(b.playerPos,b.enemyPos)>1)return toast('Ataque corpo a corpo exige estar adjacente. Mova primeiro.','error');const skill=v8LeonSkillFor({group:'weapon',name:'Kurai'}),d=rollLeon2d10(),total=d.hope+d.doom+skill;if(total>=b.enemy.cd){const dmg=2+Math.max(0,Math.floor(skill/3));b.enemy.hp=Math.max(0,b.enemy.hp-dmg);v8LeonLog(`Kurai: ${d.hope}+${d.doom}+${skill}=${total} vs CD ${b.enemy.cd}; ${dmg} dano.`,'good');if(b.enemy.hp<=0){v8LeonFinish(true);return;}}else v8LeonLog(`Kurai: ${d.hope}+${d.doom}+${skill}=${total} vs CD ${b.enemy.cd}; falha.`,'bad');v8LeonEnemyTurn();}
function v8LeonDefend(mode='defend'){const b=ui.battle;if(!b||b.over)return;b.guard=mode==='dodge'?3:2;v8LeonLog(mode==='dodge'?'Leon prepara Esquiva (+3 CD neste ataque).':'Leon assume Defesa (+2 CD neste ataque).','info');v8LeonEnemyTurn();}
function v8LeonPromptCombat(a){const fields=[];if(a.costOptions?.length)fields.push(`<label>Custo</label><select id="v8-combat-cost">${a.costOptions.map(o=>`<option value="${esc(o.label)}">${esc(o.label)} — ${o.chakra} Chakra</option>`).join('')}</select>`);if(a.variableCost)fields.push(`<label>${esc(a.variableCost.label||'Custo')}</label><input id="v8-combat-variable" class="input" type="number" min="${a.variableCost.min||0}" max="${a.variableCost.max||99}" value="${a.variableCost.min||1}">`);if(a.options?.length)fields.push(`<label>Opção</label><select id="v8-combat-option">${a.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`);if(a.kurai&&Number(a.cost?.total||0)>0)fields.push(`<label>Chakra pago por Kurai</label><input id="v8-combat-kurai" class="input" type="number" min="0" max="${Math.min(Number(a.cost.total),Number(state.character?.kurai?.chakra||0))}" value="0">`);modal(`Usar ${a.name}`,`<div class="v8-combat-modal"><img src="${esc(a.art||v8TechniqueFallback(a))}"><p>${esc(a.description||'')}</p>${fields.join('')||`<p><b>Custo:</b> ${esc(v75CostText(a.cost))}</p>`}</div>`,`<button class="btn" data-action="v8-leon-tech-confirm" data-id="${esc(a.id)}">Confirmar ação</button><button class="btn btn-secondary" data-action="close-modal">Cancelar</button>`);}
function v8LeonUseAction(id,choice={}){const b=ui.battle,a=v75Action(id);if(!b||b.over||!a)return;const text=v75Norm(`${a.name} ${a.description}`),support=/cura|defesa|prote|ancora|âncora|sensor|percepc|buff/.test(text)&&!Number(a.damage||0),range=Number(String(a.range||'').match(/\d+/)?.[0]||4),dist=gridDistance(b.playerPos,b.enemyPos);if(a.group==='weapon'&&dist>1)return toast('A arma exige aproximação.','error');if(!support&&dist>Math.max(1,range))return toast(`Alvo fora do alcance (${range}).`,'error');const cost=v75ResolvedCost(a,choice);if(!v75CanPay(cost))return toast('Recursos insuficientes para essa ação.','error');v75Deduct(cost);const skill=v8LeonSkillFor(a),d=rollLeon2d10(),total=d.hope+d.doom+skill;if(support){b.guard=Math.max(b.guard,2);v8LeonLog(`${a.name} ativada. Recursos pagos; efeito defensivo/tático preparado.`,'good');}else{if(total>=b.enemy.cd){let dmg=Number(a.damage)||Number(a.raw?.dano)||Number(a.raw?.power)||0;if(!Number.isFinite(dmg)||dmg<=0)dmg=3+Math.floor(skill/4);dmg=Math.max(1,Math.min(12,Math.round(dmg)));b.enemy.hp=Math.max(0,b.enemy.hp-dmg);v8LeonLog(`${a.name}: ${d.hope}+${d.doom}+${skill}=${total} vs CD ${b.enemy.cd}; ${dmg} dano/efeito.`,'good');if(/paralis|atordo|imobil/.test(text)&&!b.enemy.conditions.includes('Atordoado'))b.enemy.conditions.push('Atordoado');}else v8LeonLog(`${a.name}: ${d.hope}+${d.doom}+${skill}=${total} vs CD ${b.enemy.cd}; falha.`,'bad');}b.cooldowns[id]=Math.max(1,Number(a.raw?.cooldown||1));saveState(true);renderChrome();if(b.enemy.hp<=0){v8LeonFinish(true);return;}v8LeonEnemyTurn();}
function v8LeonBoard(b){const reachable=[];for(let y=0;y<5;y++)for(let x=0;x<7;x++)if(!b.moveUsed&&gridDistance(b.playerPos,{x,y})<=3)reachable.push(`${x},${y}`);return `<div class="tactical-board v8-leon-board">${b.terrain.map(c=>{const key=`${c.x},${c.y}`,p=b.playerPos.x===c.x&&b.playerPos.y===c.y,e=b.enemyPos.x===c.x&&b.enemyPos.y===c.y;return `<button class="tactical-cell ${c.type} ${reachable.includes(key)?'reachable':''}" data-action="v8-leon-move" data-x="${c.x}" data-y="${c.y}" ${p||e||b.moveUsed||b.over?'disabled':''}>${p?'<span class="tactical-unit player">🥷</span>':''}${e?'<span class="tactical-unit enemy">👺</span>':''}</button>`;}).join('')}</div>`;}
function v8RenderLeonCombat(){const c=state.character,b=ui.battle;if(!b||b.engine!=='TERION_2D10'){screen.innerHTML=`<div class="section-title"><div><span class="eyebrow">TERION 2D10 • V8</span><h1>Combate e Dojo de Leon</h1><p>Turnos reais: movimento, ataque, defesa, técnicas, dōjutsu, Kurai, itens e fuga.</p></div></div><div class="grid grid-3"><div class="card"><img src="assets/ui_v8/creator/roster/roster_01.jpg"><h3>Duelo de treino</h3><p>CD 11 • adversário padrão.</p><button class="btn" data-action="v8-start-leon" data-id="normal">Iniciar combate</button></div><div class="card"><img src="assets/ui_v8/creator/roster/roster_11.jpg"><h3>Instrutor Jōnin</h3><p>CD 14 • adversário mais resistente.</p><button class="btn btn-danger" data-action="v8-start-leon" data-id="elite">Desafiar</button></div><div class="card"><img src="assets/ui_v8/combat/actions/action_06.jpg"><h3>Diretor de Combate IA</h3><p>A IA de combate pode narrar a situação, mas não sobrescreve as rolagens do motor.</p><button class="btn btn-secondary" data-screen="mestre-ia">Abrir Mesa IA</button></div></div>`;return;}
  const actions=v75Actions().filter(a=>!a.passive&&!a.kuraiState&&['jutsu','dojutsu','ability','weapon','summon','item'].includes(a.group)).slice(0,60);screen.innerHTML=`<div class="section-title"><div><span class="eyebrow">TERION 2D10 • TURNO ${b.turn} • distância ${gridDistance(b.playerPos,b.enemyPos)}</span><h1>${esc(c.name)} × ${esc(b.enemy.name)}</h1><p>Movimento ${b.moveUsed?'usado':'disponível'} • Defesa CD ${v8LeonDefenseCD()} • Kurai ${c.kurai?.chakra||0}/${c.kurai?.maxChakra||8}</p></div><button class="btn btn-secondary" data-action="v8-leon-exit">Encerrar treino</button></div><div class="v8-leon-combat-layout"><div>${v8LeonBoard(b)}<div class="card v8-combat-log"><h3>Registro do combate</h3>${b.log.slice(-14).reverse().map(x=>`<div class="log-entry ${x.type}">${esc(x.text)}</div>`).join('')}</div></div><aside class="v8-leon-actions"><div class="card combat-hud"><div class="combatant-mini"><img src="${esc(c.avatar||'assets/ui/avatar.png')}"><div><b>${esc(c.name)}</b><small>PV ${c.hp}/${c.maxHp} • Chakra ${c.chakra}/${c.maxChakra}</small></div></div><div class="combatant-mini"><img src="${esc(b.enemy.art)}"><div><b>${esc(b.enemy.name)}</b><small>PV ${b.enemy.hp}/${b.enemy.maxHp} • CD ${b.enemy.cd}</small></div></div></div><div class="card"><h3>Ações do turno</h3><div class="v8-command-grid"><button data-action="v8-leon-basic"><img src="${v8ActionAsset(1)}"><span>Atacar</span></button><button data-action="v8-leon-defend"><img src="${v8ActionAsset(2)}"><span>Defender</span></button><button data-action="v8-leon-dodge"><img src="${v8ActionAsset(3)}"><span>Esquivar</span></button><button data-action="v8-leon-focus"><img src="${v8ActionAsset(10)}"><span>Foco Chakra</span></button><button data-action="v8-leon-flee"><img src="${v8ActionAsset(12)}"><span>Fugir</span></button><button data-action="v8-battle-ai"><img src="${v8ActionAsset(6)}"><span>Narrar combate</span></button></div></div><div class="card"><h3>Técnicas e recursos da ficha</h3><div class="v8-leon-tech-list">${actions.map(a=>`<button data-action="v8-leon-tech" data-id="${esc(a.id)}" ${(b.cooldowns[a.id]||0)>0?'disabled':''}><img src="${esc(a.art||v8TechniqueFallback(a))}"><span><b>${esc(a.name)}</b><small>${esc(v75CostText(a.cost))} • ${esc(a.range||'')}</small></span></button>`).join('')}</div></div></aside></div>`;
}
const renderCombatV8FinalBase=renderCombat;
renderCombat=function(){if(state.character?.privateCharacter==='leon'){v8RenderLeonCombat();return;}renderCombatV8FinalBase();};
const startBattleV8FinalBase=startBattle;
startBattle=function(id=null,mission=null){if(state.character?.privateCharacter==='leon'){v8StartLeonBattle(id==='elite');return;}return startBattleV8FinalBase(id,mission);};
const renderTrainingV8FinalBase=renderTraining;
renderTraining=function(){if(state.character?.privateCharacter==='leon'){screen.innerHTML=`<div class="section-title"><div><span class="eyebrow">TREINAMENTO V8 • TERION 2D10</span><h1>Dojo de Leon</h1><p>O treino agora abre o mesmo motor de turno do combate: movimentação, ataque, defesa e técnicas da ficha.</p></div><button class="btn btn-secondary" data-screen="mestre-ia">Treino narrativo IA</button></div><div class="grid grid-3"><div class="card"><img src="assets/ui_v8/creator/roster/roster_01.jpg"><h3>Treino de base</h3><button class="btn" data-action="v8-start-leon" data-id="normal">Entrar no dojo</button></div><div class="card"><img src="assets/ui_v8/creator/roster/roster_11.jpg"><h3>Treino avançado</h3><button class="btn btn-danger" data-action="v8-start-leon" data-id="elite">Desafiar instrutor</button></div><div class="card">${v8ProgressHtml(state.character)}</div></div>`;return;}renderTrainingV8FinalBase();};

const renderAIV8FinalBase=renderAI;
renderAI=function(){renderAIV8FinalBase();const mode=$('#ai-mode');if(mode){const add=[['combat_director','Combate tático'],['rules_question','Consultor de regras'],['campaign_summary','Memória / resumo'],['generate_mission','Criar missão'],['progression_review','Progressão / XP']];for(const [v,l] of add)if(![...mode.options].some(o=>o.value===v)){const o=document.createElement('option');o.value=v;o.textContent=l;mode.appendChild(o);}}const routes=ui.aiStatus?.routes||{},providers=ui.aiStatus?.providers||[];const host=screen.querySelector('.rpg-desk-title');if(host&&!screen.querySelector('.v8-router-live'))host.insertAdjacentHTML('afterend',`<section class="card v8-router-live"><div><span class="eyebrow">MULTI-IA ATIVO</span><h3>Rotas por função</h3><p>Cada pedido usa a rota correspondente; se falhar, o servidor tenta os outros provedores configurados.</p></div><div class="v8-route-grid">${Object.entries(routes).map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="provider-strip">${providers.map(p=>`<span class="provider-chip"><b>${esc(p.id)}</b><small>${esc(p.model||'')}</small></span>`).join('')}</div></section>`);};

document.addEventListener('click',async e=>{
  const t=e.target?.closest?.('[data-action]');if(!t)return;const act=t.dataset.action,id=t.dataset.id||'';
  if(act==='v8-xp-table'){const rows=v8XpTableRows();modal('Tabela de XP • níveis 1–60',`<div class="v8-xp-modal"><div class="v8-xp-table-full">${rows.map(x=>`<div><b>Nv ${x.level}</b><span>${x.level<MAX_LEVEL?`${x.xp} XP para subir`:'Nível máximo'}</span><small>NC ${x.nc} • ${esc(x.graduation)}</small></div>`).join('')}</div><div class="notice mini"><b>Regra da IA:</b> a IA nunca muda nível diretamente. Ela concede XP; o motor aplica level-up e pontos automaticamente.</div></div>`,`<button class="btn" data-action="close-modal">Fechar</button>`);return;}
  if(act==='v8-start-leon'){v8StartLeonBattle(id==='elite');return;}
  if(act==='v8-leon-move'){const b=ui.battle;if(!b||b.over||b.moveUsed)return;const pos={x:Number(t.dataset.x),y:Number(t.dataset.y)};if(gridDistance(b.playerPos,pos)>3)return;b.playerPos=pos;b.moveUsed=true;v8LeonLog(`Leon moveu para (${pos.x},${pos.y}).`,'info');saveState(true);render();return;}
  if(act==='v8-leon-basic'){v8LeonBasicAttack();return;}
  if(act==='v8-leon-defend'){v8LeonDefend('defend');return;}
  if(act==='v8-leon-dodge'){v8LeonDefend('dodge');return;}
  if(act==='v8-leon-focus'){const c=state.character,b=ui.battle;if(!b||b.over)return;const before=c.chakra;c.chakra=Math.min(c.maxChakra,Number(c.chakra||0)+2);v8LeonLog(`Foco de Chakra: ${before}→${c.chakra}.`,'good');v8LeonEnemyTurn();return;}
  if(act==='v8-leon-flee'){const b=ui.battle;if(!b||b.over)return;const sk=Number(state.character?.specialProfile?.skillRatings?.Acrobatismo??2),d=rollLeon2d10(),total=d.hope+d.doom+sk;if(total>=b.enemy.cd){v8LeonLog(`Fuga: ${d.hope}+${d.doom}+${sk}=${total}. Leon saiu do duelo.`,'good');b.over=true;saveState(true);render();}else{v8LeonLog(`Fuga falhou: ${total} vs CD ${b.enemy.cd}.`,'bad');v8LeonEnemyTurn();}return;}
  if(act==='v8-leon-tech'){const a=v75Action(id);if(a)v8LeonPromptCombat(a);return;}
  if(act==='v8-leon-tech-confirm'){const choice={costOption:$('#v8-combat-cost')?.value||'',option:$('#v8-combat-option')?.value||'',variableCost:Number($('#v8-combat-variable')?.value||0),kuraiPay:Number($('#v8-combat-kurai')?.value||0)};closeModal();v8LeonUseAction(id,choice);return;}
  if(act==='v8-leon-exit'){ui.battle=null;saveState(true);render();return;}
  if(act==='v8-battle-ai'){const result=await callAI({mode:'combat_director',prompt:'Narre somente a situação tática atual deste combate. Não rerrole, não altere PV/Chakra e não escolha a ação do jogador. Dê 2 ou 3 sugestões táticas coerentes.',state:aiGameContext(),history:ui.aiChat.slice(-8)});const tx=result?.scene?.narrative||result?.narrativa||'';modal('Diretor de Combate IA',`<p>${esc(tx).replace(/\n/g,'<br>')}</p>`,`<button class="btn" data-action="close-modal">Fechar</button>`);return;}
});


  
  // V8 final visual preview + event artwork integration.
  const renderCreateV8VisualFinalBase=renderCreate;
  renderCreate=function(){renderCreateV8VisualFinalBase();const d=getCreationDraft();v8EnsureCreationVisuals(d);const box=screen.querySelector('.v8-preview-images');if(box){const v=d.identity.visuals;box.innerHTML=`<img src="${v8CreatorAsset('hair',V8_VISUAL_INDEX.hair[v.hair]||1)}" alt="cabelo"><img src="${v8CreatorAsset('face',V8_VISUAL_INDEX.face[v.face]||1)}" alt="rosto"><img src="${v8CreatorAsset('face',V8_VISUAL_INDEX.eyes[v.eyes]||1)}" alt="olhos"><img src="${v8CreatorAsset('outfit',V8_VISUAL_INDEX.outfit[v.outfit]||1)}" alt="traje">`;}}
  try{(V74.events||[]).forEach((e,i)=>{e.art=v8EventAsset((i%20)+1);});}catch{}


  // ==================== V8.1: separação sistema geral / módulo privado Leon ====================
  const LEON81 = window.NARUTO_LEON_V81 || {};
  ui.v81GrimFilter = ui.v81GrimFilter || 'todos';
  ui.v81GrimSearch = ui.v81GrimSearch || '';
  ui.v81CodexTab = ui.v81CodexTab || 'visao';
  ui.v81CombatFilter = ui.v81CombatFilter || 'todos';
  ui.v81CombatSearch = ui.v81CombatSearch || '';

  // Usa todo o pacote visual criado: 16 cabelos, 16 rostos/olhos e 16 trajes.
  if(V8_HAIR.length<16)V8_HAIR.push('Ondulado longo','Coque alto','Franja cobrindo um olho','Camadas médias');
  if(V8_FACE.length<16)V8_FACE.push('Rosto com cicatriz','Rosto com sardas','Rosto com pintura','Rosto com selo','Rosto com tapa-olho','Rosto confiante','Rosto estoico','Rosto maduro');
  if(V8_EYES.length<16)V8_EYES.push('Olhos afiados','Olhos tranquilos','Olhos dourados','Olhos violeta','Olhos de caçador','Olhos cansados','Olhos intensos','Olhos suaves');
  if(V8_OUTFITS.length<16)V8_OUTFITS.push('Traje de invocador','Traje de kenjutsu','Casaco de inverno','Traje de areia','Traje da névoa','Traje tecnológico');
  Object.assign(V8_VISUAL_INDEX.hair,Object.fromEntries(V8_HAIR.map((x,i)=>[x,i+1])));
  Object.assign(V8_VISUAL_INDEX.face,Object.fromEntries(V8_FACE.map((x,i)=>[x,i+1])));
  Object.assign(V8_VISUAL_INDEX.eyes,Object.fromEntries(V8_EYES.map((x,i)=>[x,Math.min(16,i+1)])));
  Object.assign(V8_VISUAL_INDEX.outfit,Object.fromEntries(V8_OUTFITS.map((x,i)=>[x,i+1])));

  function v81IsLeon(){ return state.character?.privateCharacter === 'leon'; }
  function v81LeonCaps(){
    return (LEON81.capacidadesOperacionais||[]).filter(x=>['ATIVO_NIVEL_1','ATIVA_NIVEL_1','ATIVO','ATIVA','ATIVO_POS_TREINO','ATIVA_POS_TREINO'].includes(String(x.status||'').toUpperCase()));
  }
  function v81CapGroup(x){
    const id=String(x?.id||''), t=v75Norm(`${x?.nome||''} ${x?.categoria||''} ${x?.fonte||''}`);
    if(id.startsWith('SUIRIN_')) return 'suirin';
    if(id==='ITEM_KURAI'||id.startsWith('KURAI_')||/kurai|arma_viva/.test(t)) return 'kurai';
    if(id.startsWith('KUSENRO_')||Number(x?.custo?.chakraKusenro||0)>0||/kusenro|jinchuriki_espacial|biju/.test(t)) return 'kusenro';
    if(id.startsWith('KUGANGAN_')||/kugangan|dojutsu|ocular/.test(t)) return 'dojutsu';
    if(id.startsWith('CLONE_')||/clone|bunshin/.test(t)) return 'clone';
    if(/invoc|kuchiyose/.test(t)) return 'summon';
    return 'jutsu';
  }
  function v81PaletteGroup(group){
    return ({suirin:'summon',kurai:'weapon',kusenro:'ability',clone:'summon',summon:'summon',dojutsu:'dojutsu',jutsu:'jutsu'})[group]||'jutsu';
  }
  function v81CapArt(x){
    const g=v81CapGroup(x), text=v75Norm(`${x?.nome||''} ${x?.categoria||''}`);
    if(g==='suirin') return text.includes('mordida')?v8TechAsset(11):text.includes('rastreio')?v8TechAsset(12):v8TechAsset(10);
    if(g==='kusenro') return /manto|presa|caudas|bijudama/.test(text)?v8TechAsset(18):/passo|asas|senko/.test(text)?v8TechAsset(20):v8TechAsset(19);
    if(g==='kurai') return 'assets/rpg_v75/kurai_v75.svg';
    if(g==='dojutsu') return v8TechAsset(9);
    return v8TechniqueFallback({name:x?.nome,description:x?.descricaoObjetiva,element:x?.categoria});
  }
  function v81ActionId(x){
    const g=v81CapGroup(x),id=String(x.id||v75Norm(x.nome));
    if(g==='kurai') return id==='ITEM_KURAI'?'item:kurai_state':`kurai:${id}`;
    if(g==='suirin') return `suirin:${id}`;
    if(g==='kusenro') return `kusenro:${id}`;
    return `leon81:${id}`;
  }
  function v81SyncLeonPrivate(){
    if(!v81IsLeon()||!LEON81.recursos)return;
    const c=state.character,r=LEON81.recursos;
    c.maxHp=Number(c.maxHp||r.PV?.maximo||16); c.hp=clamp(Number(c.hp??r.PV?.atual??16),0,c.maxHp);
    c.maxChakra=Number(c.maxChakra||r.ChakraComum?.maximo||18); c.chakra=clamp(Number(c.chakra??r.ChakraComum?.atual??18),0,c.maxChakra);
    c.kusenroMaxChakra=Number(c.kusenroMaxChakra||r.ChakraKusenro?.maximo||6); c.kusenroChakra=clamp(Number(c.kusenroChakra??r.ChakraKusenro?.atual??6),0,c.kusenroMaxChakra);
    const k=LEON81.kurai?.ficha?.ficha||{}; c.kurai=c.kurai||{};
    c.kurai.maxPv=Number(c.kurai.maxPv||k.PVMaximo||8); c.kurai.pv=clamp(Number(c.kurai.pv??k.PVAtual??8),0,c.kurai.maxPv);
    c.kurai.maxChakra=Number(c.kurai.maxChakra||k.ChakraMaximo||8); c.kurai.chakra=clamp(Number(c.kurai.chakra??k.ChakraAtual??8),0,c.kurai.maxChakra); c.kurai.mode=c.kurai.mode||'guardada';
    c.privateModule={id:'leon-v81',isolated:true,totalCapabilities:v81LeonCaps().length,sourceVersion:LEON81.versaoFonte||'5.1-kugangan-mimetico'};
  }

  const ensureV75StateV81Base=ensureV75State;
  ensureV75State=function(){ const s=ensureV75StateV81Base(); v81SyncLeonPrivate(); return s; };

  // O módulo do Leon substitui o catálogo privado antigo e nunca é usado por personagens comuns.
  v75LeonActions=function(){
    v81SyncLeonPrivate(); const out=[];
    const standard=[
      ['basic_attack','Ataque básico','Ação principal','Ataque corporal ou com a arma que Leon declarar.','Corpo a corpo','Alvo'],
      ['move','Mover / Reposicionar','Movimento','Move até o deslocamento permitido, respeitando terreno e ocupação.','Deslocamento','Leon'],
      ['defend','Defender','Ação/Reação','Assume postura defensiva, cobertura, bloqueio ou aparo conforme a situação.','Pessoal','Leon'],
      ['dodge','Esquivar','Reação','Tenta evitar um ataque com movimentação e leitura do golpe.','Pessoal','Leon'],
      ['observe','Observar / Procurar','Ação','Lê o ambiente, pistas, Chakra, ameaças e distorções perceptíveis.','Cena','Área/alvo'],
      ['interact','Interagir','Ação','Manipula objetos, mecanismos, selos e elementos do cenário.','Toque/alcance','Objeto'],
      ['talk','Falar / Negociar','Ação narrativa','Fala, pergunta, negocia, blefa, intimida ou tenta convencer.','Audição','NPC/alvo'],
      ['prepare','Preparar ação','Ação','Define gatilho e resposta para uma ação preparada.','Conforme ação','Gatilho']
    ];
    for(const [id,name,activation,description,range,target] of standard)out.push({id:`action:${id}`,name,group:'acao',activation,cost:{chakraComum:0},description,art:v8ActionAsset(({basic_attack:1,defend:2,dodge:3,move:4,observe:6,interact:9,talk:6,prepare:11})[id]||6),range,target,leon:true});
    for(const t of v81LeonCaps()){
      const priv=v81CapGroup(t),palette=v81PaletteGroup(priv), id=v81ActionId(t);
      if(t.id==='ITEM_KURAI'){
        out.push({id,name:'Kurai — Forma de uso',aliases:['Kurai','arma viva','equipar','guardar','empunhar'],group:'item',privateGroup:'kurai',activation:'Ação de equipamento',cost:{chakraComum:0},description:t.descricaoObjetiva||LEON81.kurai?.ficha?.descricaoObjetiva||'',art:'assets/rpg_v75/kurai_v75.svg',range:'Pessoal',target:'Kurai',options:['Empunhada','Guardada'],leon:true,kuraiState:true,raw:t});
        continue;
      }
      out.push({id,sourceId:t.id,name:t.nome,aliases:[t.id,t.categoria,t.fonte,priv, priv==='kusenro'?'Kūsenrō':'', priv==='suirin'?'Suirin':'',priv==='kurai'?'Kurai':''].filter(Boolean),group:palette,privateGroup:priv,activation:t.ativacao||'Ação',cost:t.custo||{},description:t.descricaoObjetiva||(t.efeitos||[]).join(' • '),art:v81CapArt(t),range:t.alcance||'Conforme ficha',target:t.alvo||'Conforme técnica',damage:t.dano||0,test:t.teste||{},limit:(t.limites||[]).join(' • '),raw:t,leon:true,kurai:priv==='kurai',suirin:priv==='suirin',kusenro:priv==='kusenro',passive:/passiva/i.test(String(t.categoria||''))&&Number(t.custo?.chakraComum||0)===0&&Number(t.custo?.chakraKusenro||0)===0});
    }
    // Itens ordinários continuam disponíveis; poderes privados não são adicionados ao sistema comum.
    for(const [id,q] of Object.entries(state.inventory||{})){
      if(Number(q)<=0)continue;const i=itemById(id);if(!i)continue;const group=i.tipo==='arma'?'weapon':'item';
      out.push({id:`${group}:${id}`,sourceId:id,name:i.nome,aliases:[id,i.tipo,'inventário'],group,privateGroup:'item',activation:group==='weapon'?'Ataque / Equipar':'Ação de item',cost:{chakraComum:0},description:itemDescription(i),art:v7ItemArt(i),range:i.alcance||'Conforme item',target:group==='weapon'?'Alvo':'Usuário/Alvo',quantity:q,damage:i.dano||0,raw:i,leon:true});
    }
    return out;
  };

  const renderChromeV81Base=renderChrome;
  renderChrome=function(){
    renderChromeV81Base(); const c=state.character;if(!c)return;
    if(c.privateCharacter==='leon'){
      v81SyncLeonPrivate(); const need=c.level>=MAX_LEVEL?0:xpNeeded(c.level), pc=c.level>=MAX_LEVEL?100:Math.round((Number(c.xp||0)/Math.max(1,need))*100);
      topResources.innerHTML=`<span class="resource-pill live hp">❤️ <b>${c.hp}/${c.maxHp}</b></span><span class="resource-pill live chakra">🔵 <b>${c.chakra}/${c.maxChakra}</b></span><span class="resource-pill live kusenro">🌌 Kūsenrō <b>${c.kusenroChakra}/${c.kusenroMaxChakra}</b></span><span class="resource-pill live xp">⭐ XP <b>${c.level>=MAX_LEVEL?'MÁX':`${c.xp}/${need}`}</b> <i style="--p:${pc}%"></i></span>`;
    }
  };

  const v75SheetPanelV81Base=v75SheetPanel;
  v75SheetPanel=function(c){
    if(c?.privateCharacter!=='leon')return v75SheetPanelV81Base(c);
    v81SyncLeonPrivate(); const attrs=c.specialProfile?.coreAttributes||V75.leon?.character?.atributosFinais||{},skills=c.specialProfile?.skillRatings||V75.leon?.character?.pericias||{};
    return `<div class="rpg-sheet-head"><img src="${esc(c.avatar||'assets/private/leon_kosmo_avatar.jpg')}"><div><span class="eyebrow">FICHA AO VIVO</span><h2>Leon Kosmo</h2><small>TERION SHINOBI 2D10 • ${v81LeonCaps().length} capacidades ativas</small></div></div><div class="rpg-resources-v75">${v75ResourceControls('hp',c.hp,c.maxHp,'PV')}${v75ResourceControls('chakra',c.chakra,c.maxChakra,'Chakra')}${v75ResourceControls('kusenro',c.kusenroChakra,c.kusenroMaxChakra,'Kūsenrō')}</div>${v75ConditionRow(c)}${v8ProgressHtml(c)}<div class="rpg-roll-cd"><label>CD do teste</label><input id="rpg-roll-cd" type="number" min="2" max="40" value="${ui.rpgRollDifficulty}"></div><h4>Atributos • clique para rolar</h4><div class="rpg-stat-grid">${Object.entries(attrs).map(([k,v])=>`<button data-action="rpg-roll" data-id="${esc(k)}"><span>${esc(k)}</span><b>${v}</b></button>`).join('')}</div><details open><summary>Perícias • clique para rolar</summary><div class="rpg-skill-list">${Object.entries(skills).map(([k,v])=>`<button data-action="rpg-roll" data-id="${esc(k)}"><span>${esc(k)}</span><b>${v}</b></button>`).join('')}</div></details><div class="sheet-quick-v75"><button class="btn btn-secondary" data-screen="tecnicas">📜 Grimório</button><button class="btn btn-secondary" data-screen="enciclopedia">📚 Recursos</button><button class="btn btn-secondary" data-screen="progressao">⭐ Progressão</button></div>`;
  };

  // Mesa com filtros privados explícitos; os grupos do Leon ficam organizados sem misturar catálogo mundial.
  renderAIV75=function(){
    ensureV75State();const c=state.character;if(!c)return;
    const all=v75Actions(),q=v75Norm(ui.rpgSearch),tab=ui.rpgTab||'todos';
    const tabDefs=c.privateCharacter==='leon'?[['todos','Tudo'],['jutsu','Jutsus'],['dojutsu','Dōjutsu'],['kusenro','Kūsenrō'],['suirin','Suirin'],['kurai','Kurai'],['clone','Clones'],['item','Itens'],['acao','Ações']]:[['todos','Tudo'],['jutsu','Jutsus'],['dojutsu','Dōjutsu'],['ability','Habilidades'],['weapon','Armas'],['item','Itens'],['summon','Invocações'],['acao','Ações']];
    const matchTab=a=>tab==='todos'||(c.privateCharacter==='leon'?(a.privateGroup===tab||(tab==='item'&&a.group==='item')||(tab==='acao'&&a.group==='acao')):a.group===tab);
    const actions=all.filter(a=>matchTab(a)&&(!q||v75Norm(`${a.name} ${(a.aliases||[]).join(' ')} ${a.description} ${a.activation} ${a.range||''}`).includes(q)));
    const count=id=>id==='todos'?all.length:all.filter(a=>c.privateCharacter==='leon'?(a.privateGroup===id||(id==='item'&&a.group==='item')||(id==='acao'&&a.group==='acao')):a.group===id).length;
    const narrative=ui.aiDraft?.scene?.narrative||ui.aiDraft?.narrativa||'',options=ui.aiDraft?.options||ui.aiDraft?.scene?.options||[],test=ui.aiDraft?.resolution?.test||null,selected=v75Action(ui.rpgSelected);
    const testBox=test?`<section class="card rpg-test-request-v75"><div><span class="eyebrow">TESTE PEDIDO PELO MESTRE</span><h3>${esc(test.reason||'Resolver ação')}</h3><p>${c.privateCharacter==='leon'?`TERION 2D10 • ${esc(test.skill||test.attribute||'modificador')} contra CD ${esc(test.difficulty||ui.rpgRollDifficulty)}`:`TERION 2D10 • ${esc(test.skill||test.attribute||test.combatStat||'modificador')} contra CD ${esc(test.difficulty||ui.rpgRollDifficulty)}`}</p></div><button class="btn" data-action="ai-check">🎲 Rolar teste</button></section>`:'';
    const last=ui.rpgLastSpend&&Date.now()-ui.rpgLastSpend.at<120000?ui.rpgLastSpend:null;
    screen.innerHTML=`<div class="rpg-desk-title v76"><div><span class="eyebrow">MESA DE RPG.1</span><h1>Mestre, ficha, XP e ações reais da ficha</h1><p>${c.privateCharacter==='leon'?'O módulo privado mostra somente as 75 capacidades ativas de Leon + seus itens. Nenhum poder privado entra em outro personagem.':'A paleta mostra somente técnicas, itens e ações disponíveis para esta ficha.'}</p></div><div class="button-row"><button class="btn btn-secondary" data-screen="vila">🗺️ Mapa</button><button class="btn btn-secondary" data-screen="personagem">📋 Ficha</button><button class="btn btn-secondary" data-screen="progressao">⭐ XP</button><button class="btn" data-action="save">💾 Salvar</button></div></div>${last?`<div class="spend-flash-v76"><b>Gasto aplicado:</b> ${esc(last.name)} • Chakra ${last.before?.chakra??'?'} → ${last.after?.chakra??'?'}${last.cost.kurai?` • Kurai ${last.before?.kurai??'?'} → ${last.after?.kurai??'?'}`:''}${last.cost.kusenro?` • Kūsenrō ${last.before?.kusenro??'?'} → ${last.after?.kusenro??'?'}`:''}</div>`:''}<div class="rpg-desk-v76"><aside class="rpg-sheet-v76 card">${v75SheetPanel(c)}</aside><main class="rpg-narrative-v76"><section class="card narrative-stage v76"><div class="narrative-head"><div><span class="eyebrow">CENA ATUAL</span><h2>${esc(ui.aiDraft?.scene?.title||state.campaign?.name||'Campanha')}</h2></div><span class="ai-open-ok"><span>●</span> ${ui.aiPending?'Mestre pensando...':ui.aiStatus.enabled?'IA conectada':'Narrador offline'}</span></div>${narrative?`<div class="narrative-text v76">${esc(narrative).replace(/\n/g,'<br>')}</div>`:'<div class="narrative-empty"><b>Pronto para jogar.</b><span>Escolha uma ação real da sua ficha ou descreva livremente o que pretende fazer.</span></div>'}${options.length?`<div class="narrative-options">${options.map((o,i)=>`<button class="choice-card" data-action="rpg-option" data-id="${i}"><b>${i+1}</b><span>${esc(o?.label||o?.text||String(o))}</span></button>`).join('')}</div>`:''}</section>${testBox}${v75EffectsPanel()}<section class="card rpg-compose v76"><textarea id="ai-prompt" placeholder="Descreva exatamente o que ${esc(c.name)} faz, fala, procura ou tenta..."></textarea><div class="rpg-compose-actions"><select id="ai-mode"><option value="game_master">Mestre de jogo</option><option value="npc_dialogue">Interpretar NPC</option><option value="investigation">Investigação</option><option value="training">Treino</option><option value="combat_director">Combate tático</option><option value="rules_question">Regras</option><option value="campaign_summary">Memória</option><option value="generate_mission">Missões</option><option value="progression_review">Progressão / XP</option></select><button class="btn" data-action="ai-custom" ${ui.aiPending?'disabled':''}>🎭 Narrar ação</button><button class="btn btn-secondary" data-action="rpg-continue" ${ui.aiPending?'disabled':''}>Continuar sem agir</button></div></section><section class="card rpg-log"><h3>Rolagens, gastos e alterações</h3><div>${ui.rpgLog.slice(-18).reverse().map(x=>`<div class="rpg-log-line ${x.type||''}">${esc(x.text)}</div>`).join('')||'<p class="muted">Nenhuma ação registrada ainda.</p>'}</div></section></main><aside class="rpg-palette-v76"><div class="card palette-head v76"><div class="rpg-tabs v76">${tabDefs.map(([id,l])=>`<button class="${tab===id?'active':''}" data-action="rpg-tab" data-id="${id}">${l}<b>${count(id)}</b></button>`).join('')}</div><div class="search-wrap-v76"><span>⌕</span><input id="rpg-search" class="input" value="${esc(ui.rpgSearch)}" placeholder="Buscar na ficha atual..."></div><small>${c.privateCharacter==='leon'?'Privado: Kūsenrō, Suirin, Kurai e Projeto Kosmo pertencem somente ao Leon.':'Conteúdo de outros personagens/clãs não é exibido como utilizável.'}</small></div>${selected?`<section class="selected-action-v76 card"><span class="eyebrow">AÇÃO SELECIONADA</span><div class="selected-action-head-v76"><img src="${esc(selected.art||'assets/rpg_v75/action.svg')}"><div><b>${esc(selected.name)}</b><small>${esc(v75CostText(selected.cost))}</small></div></div><p>${esc(selected.description||'')}</p></section>`:''}<div class="rpg-action-list v76">${actions.map(v75ActionCard).join('')||'<div class="card"><p>Nenhuma ação disponível neste filtro.</p></div>'}</div></aside></div>`;
  };
  const renderAIV81RoutesBase=renderAIV75;
