  function v821LeonLocalState(){
    try{const raw=localStorage.getItem(LEON_LOCAL_KEY);return v821ApplyLeonCanonical(hydrateState(raw?JSON.parse(raw):v821Clone(LEON_TEMPLATE_V821)));}
    catch(e){console.warn('Save local de Leon inválido; usando a ficha oficial.',e);return v821ApplyLeonCanonical(hydrateState(v821Clone(LEON_TEMPLATE_V821)));}
  }
  function v821LoadLeon(){
    if(!LEON_TEMPLATE_V821)return toast('Ficha consolidada de Leon não encontrada.','error',5000);
    activeSlotId='';localStorage.removeItem(ACTIVE_SLOT_KEY);state=v821LeonLocalState();ensureV7State();
    ui.aiChat=state.ai?.history||[];ui.aiDraft=state.ai?.lastDraft||null;ui.aiLastCheck=state.ai?.lastCheck||null;ui.battle=null;ui.screen='inicio';
    saveState(true);render();toast('Leon v5.6 carregado e pronto para jogar.','success',4500);
  }
  function v821ResetLeon(){
    localStorage.removeItem(LEON_LOCAL_KEY);
    if(state.character?.privateCharacter==='leon'){state=v821LeonLocalState();ensureV7State();saveState(true);ui.screen='inicio';}
    render();toast('Ficha local de Leon restaurada para o Save Point v5.6.','success',4500);
  }

  const saveStateV821Base=saveState;
  saveState=function(silent=false){
    if(state.character?.privateCharacter!=='leon')return saveStateV821Base(silent);
    v821ApplyLeonCanonical(state);state.version=APP_VERSION;state.updatedAt=Date.now();
    localStorage.setItem(LEON_LOCAL_KEY,JSON.stringify(state));sessionStorage.setItem('sns-private-session-state',JSON.stringify(state));
    if(!silent)toast('Leon salvo neste computador.','success');
  };

  const saveCampaignNowV821Base=saveCampaignNow;
  saveCampaignNow=async function(){
    if(state.character?.privateCharacter!=='leon')return saveCampaignNowV821Base();
    saveState(true);let cloudOk=false;
    if(ui.privateSessionToken&&ui.aiStatus.cloudSave)cloudOk=await leonSave(true);
    toast(cloudOk?'Leon salvo localmente e sincronizado.':'Leon salvo neste computador.','success',4200);render();return true;
  };

  const importSaveV821Base=importSave;
  importSave=function(file){
    const reader=new FileReader();reader.onload=()=>{try{
      const loaded=JSON.parse(reader.result);if(!loaded?.character)throw new Error('Arquivo sem personagem');
      if(loaded.character.privateCharacter!=='leon'){importSaveV821Base(file);return;}
      activeSlotId='';localStorage.removeItem(ACTIVE_SLOT_KEY);state=v821ApplyLeonCanonical(hydrateState(loaded));ensureV7State();
      ui.aiChat=state.ai?.history||[];ui.aiDraft=state.ai?.lastDraft||null;ui.aiLastCheck=state.ai?.lastCheck||null;ui.screen='inicio';saveState(true);render();toast('Save de Leon importado e atualizado para v5.6.','success',5000);
    }catch(e){toast(`Save inválido: ${e.message}`,'error',5000);}};reader.readAsText(file);
  };

