  function v821LoadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});}
  function v821DrawCrop(ctx,img,sx,sy,sw,sh,dx,dy,dw,dh){ctx.drawImage(img,sx,sy,sw,sh,dx,dy,dw,dh);}
  async function v821DrawAvatar(canvas,visuals){
    if(!canvas)return false;const v=visuals||{},idx=k=>V8_VISUAL_INDEX[k]?.[v[k]]||1;
    const [hair,face,eyes,outfit]=await Promise.all([
      v821LoadImage(v8CreatorAsset('hair',idx('hair'))),v821LoadImage(v8CreatorAsset('face',idx('face'))),
      v821LoadImage(v8CreatorAsset('face',idx('eyes'))),v821LoadImage(v8CreatorAsset('outfit',idx('outfit')))
    ]);
    const size=420;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,size,size);
    const bg=ctx.createRadialGradient(210,170,30,210,210,300);bg.addColorStop(0,'#55301c');bg.addColorStop(.55,'#18100d');bg.addColorStop(1,'#070606');ctx.fillStyle=bg;ctx.fillRect(0,0,size,size);
    ctx.save();ctx.beginPath();ctx.roundRect(20,18,380,382,30);ctx.clip();
    v821DrawCrop(ctx,hair,Math.round(hair.width*.08),0,Math.round(hair.width*.84),hair.height,8,0,404,315);
    ctx.save();ctx.beginPath();ctx.ellipse(210,174,112,125,0,0,Math.PI*2);ctx.clip();
    v821DrawCrop(ctx,face,Math.round(face.width*.20),Math.round(face.height*.10),Math.round(face.width*.60),Math.round(face.height*.62),102,62,216,226);
    ctx.globalAlpha=.93;v821DrawCrop(ctx,eyes,Math.round(eyes.width*.18),Math.round(eyes.height*.18),Math.round(eyes.width*.64),Math.round(eyes.height*.33),101,92,218,100);ctx.restore();
    ctx.save();ctx.beginPath();ctx.roundRect(78,250,264,170,24);ctx.clip();v821DrawCrop(ctx,outfit,Math.round(outfit.width*.25),Math.round(outfit.height*.33),Math.round(outfit.width*.55),Math.round(outfit.height*.45),75,238,270,190);ctx.restore();
    const shade=ctx.createLinearGradient(0,250,0,420);shade.addColorStop(0,'rgba(0,0,0,0)');shade.addColorStop(1,'rgba(0,0,0,.45)');ctx.fillStyle=shade;ctx.fillRect(0,230,420,190);ctx.restore();
    ctx.strokeStyle='#f29234';ctx.lineWidth=6;ctx.strokeRect(8,8,404,404);ctx.strokeStyle='rgba(255,220,160,.6)';ctx.lineWidth=1;ctx.strokeRect(17,17,386,386);return true;
  }
  async function v821ComposeAvatarDataUrl(visuals){const canvas=document.createElement('canvas');await v821DrawAvatar(canvas,visuals);return canvas.toDataURL('image/jpeg',.9);}

  const renderCreateV821Base=renderCreate;
