    const d=getCreationDraft();v8EnsureCreationVisuals(d);
    if(!d.identity.customAvatar){try{const signature=JSON.stringify(d.identity.visuals);d.identity.avatar=d.identity.composedAvatarSignature===signature&&String(d.identity.composedAvatar||'').startsWith('data:image/')?d.identity.composedAvatar:await v821ComposeAvatarDataUrl(d.identity.visuals);writeCreationDraft();}catch(e){console.warn('Avatar composto indisponível; usando avatar padrão.',e);}}
