  function v83SkillValue(key){const c=state.character,m=v83EnsureState(),ratings=c?.specialProfile?.skillRatings||{},core=c?.specialProfile?.coreAttributes||{};const map={ninjutsu:'Ninjutsu',taijutsu:'Taijutsu',genjutsu:'Genjutsu',bukijutsu:'Armas Ninja',armas:'Armas Ninja',forca:'Corpo',resistencia:'Corpo',agilidade:'Tecnica',inteligencia:'Mente',espirito:'Espirito'};const target=map[v75Norm(key)]||key,base=Number(ratings[target]??core[target]??0),advance=Number(m?.training?.skillAdvances?.[target]||0);return base+advance;}
  function v83EligibleMentorIds(j){const text=v75Norm(`${j?.name||''} ${j?.class||''} ${j?.elementReq||''}`);if(/raiton/.test(text))return['kakashi','mentor_viajante'];if(/taijutsu|tai/.test(text))return['gai','anko','mentor_campo'];if(/buk|kenjutsu|arma/.test(text))return['anko','mentor_campo'];if(/sensor|rastrei|percepc/.test(text))return['mentor_sensorial','kakashi'];if(/fuuin|sel/.test(text))return['mentor_selamento','kakashi'];return['iruka','kakashi','mentor_viajante'];}
  function v83AcquireDecision(j){const m=v83EnsureState(),owned=(m.acquiredCatalog||[]).includes(j.id)||v81LeonCaps().some(x=>v75Norm(x.nome)===v75Norm(j.name)),reasons=[];if(owned)return {owned:true,trainable:false,state:'NA_FICHA',reason:'Já pertence à ficha'};const rank=String(j.rank||'').toLowerCase(),rankAllowed=['','estudante','genin'].includes(rank);if(Number(j.graduation??0)>1||!rankAllowed)reasons.push(`Escala ${j.rank||'acima de Genin'} bloqueada no estado atual`);const affinity=String(j.elementReq||'').toLowerCase();if(affinity&&!['katon','raiton'].includes(affinity))reasons.push(`Afinidade ${affinity} não treinada`);for(const [req,n] of Object.entries(j.requirements||{})){const have=v83SkillValue(req);if(have<Number(n))reasons.push(`${req} ${have}/${n}`);}const blocked=(LEON81.blockedScale||[]).find(x=>v75Norm(j.name).includes(v75Norm(String(x).split('/')[0])));if(blocked)reasons.push('Bloqueado explicitamente pela ficha v5.6');const mentors=v83EligibleMentorIds(j),known=mentors.some(id=>m.trainers[id]?.discovered);if(!known)reasons.push('Fonte ou mentor ainda não descoberto');return {owned:false,trainable:reasons.length===0,state:reasons.length?'BLOQUEADO_POR_REQUISITO':'PODE_ENTRAR_EM_TREINO',reason:reasons.join(' • ')||'Requisitos atuais confirmados',mentorIds:mentors};}
  function v83ProjectFor(j){return v83EnsureState()?.training?.projects?.[`catalog:${j.id}`]||null;}
  function v83StartProject(id){const j=jutsuById(id),m=v83EnsureState();if(!j||!m)return;const d=v83AcquireDecision(j);if(!d.trainable)return toast(d.reason||'Esta técnica não pode ser adquirida agora.','error',6500);const key=`catalog:${id}`;if(!m.training.projects[key])m.training.projects[key]={id:key,targetId:id,name:j.name,type:'catalog',status:'EM_TREINO',progressMinutes:0,requiredMinutes:(j.rank==='Estudante'?240:480),successes:0,failures:0,sourceValidated:false,mentorId:'',startedAt:v83ClockLabel(m.clock),requirementsSnapshot:v83Copy(j.requirements||{})};v83Commit('training_project_started',{label:`Projeto de treino iniciado: ${j.name}`,techniqueId:id},15);saveState(true);ui.v83TrainTab='projetos';ui.screen='treino';render();}
  function v83TrainingMentor(project){const el=document.getElementById(`v83-mentor-${v75Norm(project.id)}`);return el?.value||project.mentorId||'';}
  function v83ProjectSession(projectId){const m=v83EnsureState(),p=m.training.projects[projectId],j=jutsuById(p?.targetId);if(!p||!j)return;const current=v83AcquireDecision(j);if(current.owned){p.status='CONCLUIDO';return render();}if(!current.trainable)return toast(current.reason,'error',6500);const mentorId=v83TrainingMentor(p),mentor=m.trainers[mentorId];if(!mentor?.discovered||!mentor.available)return toast('Escolha um mentor descoberto e disponível neste horário/local.','error',6500);if(!v83EligibleMentorIds(j).includes(mentorId))return toast(`${mentor.name} não é uma fonte válida para esta técnica.`,'error',6500);const skill=j.class==='tai'?'Taijutsu':j.class==='buk'?'Armas Ninja':'Ninjutsu',roll=v82TrainingRoll(skill);p.mentorId=mentorId;p.sourceValidated=true;p.progressMinutes=Math.min(p.requiredMinutes,p.progressMinutes+(roll.success?180:90));p[roll.success?'successes':'failures']=Number(p[roll.success?'successes':'failures']||0)+1;if(p.progressMinutes>=p.requiredMinutes&&p.successes>=2)p.status='PRONTO_PARA_PROVA';const line=`${v83ClockLabel(m.clock)} • ${j.name} com ${mentor.name}: ${roll.text} • ${roll.success?'sucesso':'falha'} • ${Math.round(p.progressMinutes/60)}/${Math.round(p.requiredMinutes/60)}h.`;m.training.history.unshift(line);m.training.history=m.training.history.slice(0,80);v83Commit('training_session',{label:`Sessão de treino: ${j.name}`,projectId,mentor:mentor.name,success:roll.success},180);saveState(true);render();}
  function v83FinalizeProject(projectId){const m=v83EnsureState(),p=m.training.projects[projectId],j=jutsuById(p?.targetId);if(!p||!j||p.status!=='PRONTO_PARA_PROVA')return;const d=v83AcquireDecision(j);if(!d.trainable)return toast(`A prova foi bloqueada: ${d.reason}`,'error',6500);if(!p.sourceValidated)return toast('A fonte/mentor do projeto ainda não foi validada.','error');const roll=v82TrainingRoll(j.class==='tai'?'Taijutsu':j.class==='buk'?'Armas Ninja':'Ninjutsu');v83Commit('training_final_test',{label:`Prova final: ${j.name}`,projectId,success:roll.success},60);if(!roll.success){p.failures++;m.training.history.unshift(`${v83ClockLabel(m.clock)} • prova de ${j.name}: ${roll.text} • falha; projeto continua aberto.`);saveState(true);render();return;}m.acquiredCatalog.push(j.id);m.acquiredCatalog=Array.from(new Set(m.acquiredCatalog));if(!state.learned.includes(j.id))state.learned.push(j.id);p.status='CONCLUIDO';p.completedAt=v83ClockLabel(m.clock);v83SavePoint(`Técnica adquirida: ${j.name}`,[`Projeto ${projectId} concluído`,`Fonte: ${m.trainers[p.mentorId]?.name||p.mentorId}`,`Requisitos revalidados na prova final`]);m.training.history.unshift(`${v83ClockLabel(m.clock)} • ${j.name} adquirida e vinculada à ficha.`);saveState(true);toast(`${j.name} foi adquirida e agora aparece na ficha.`,'success',5500);render();}
  function v83PracticeOwned(){const m=v83EnsureState(),id=document.getElementById('v83-practice-tech')?.value,method=document.getElementById('v83-practice-method')?.value||'solo',cap=v81LeonCaps().find(x=>x.id===id);if(!cap)return toast('Escolha uma capacidade da ficha.','error');const minutes=method==='mentor'?180:method==='dojo'?90:60,skill=cap.teste?.pericia||'Ninjutsu',roll=v82TrainingRoll(skill),rec=m.training.mastery[id]||{minutes:0,successes:0,failures:0};rec.minutes+=minutes;rec[roll.success?'successes':'failures']++;rec.lastMethod=method;m.training.mastery[id]=rec;const line=`${v83ClockLabel(m.clock)} • prática de ${cap.nome}: ${roll.text} • ${roll.success?'sucesso':'falha'} • ${minutes} min.`;m.training.history.unshift(line);m.training.history=m.training.history.slice(0,80);v83Commit('training_practice',{label:`Prática: ${cap.nome}`,techniqueId:id,method,success:roll.success},minutes);saveState(true);render();}
  function v83PracticeSkillAdvance(){const m=v83EnsureState(),skill=document.getElementById('v83-practice-skill')?.value;if(!skill)return;const rec=m.training.skillProjects[skill]||{sessions:0,successes:0,failures:0,minutes:0},roll=v82TrainingRoll(skill);rec.sessions++;rec.minutes+=180;rec[roll.success?'successes':'failures']++;let advanced=false;if(rec.successes>=3&&rec.minutes>=540){m.training.skillAdvances[skill]=Number(m.training.skillAdvances[skill]||0)+1;rec.sessions=0;rec.successes=0;rec.failures=0;rec.minutes=0;advanced=true;v83SavePoint(`Perícia desenvolvida: ${skill}`,[`${skill} recebe +1 por treino registrado`,`Três sucessos e nove horas confirmados`]);}m.training.skillProjects[skill]=rec;m.training.history.unshift(`${v83ClockLabel(m.clock)} • desenvolvimento de ${skill}: ${roll.text} • ${roll.success?'sucesso':'falha'}${advanced?' • +1 permanente no estado V8.4':''}.`);m.training.history=m.training.history.slice(0,80);v83Commit('skill_training',{label:`Treino de perícia: ${skill}`,skill,success:roll.success,advanced},180);saveState(true);if(advanced)toast(`${skill} avançou +1 e novos requisitos serão recalculados.`,'success',5500);render();}
  function v83VisibleMentors(){const m=v83EnsureState();return Object.values(m.trainers).filter(x=>x.discovered);}
  function v83MentorOptions(project){const m=v83EnsureState(),ids=v83EligibleMentorIds(jutsuById(project.targetId));return ids.filter(id=>m.trainers[id]?.discovered).map(id=>{const x=m.trainers[id];return `<option value="${id}" ${project.mentorId===id?'selected':''} ${x.available?'':'disabled'}>${esc(x.name)} — ${esc(x.specialty)}${x.available?'':' (indisponível)'}</option>`;}).join('');}
  function v83MissionExercise(){const m=v83EnsureState(),run=ui.currentMission;if(!run)return'';const rec=m.missions[run.id],p=rec?.pending;if(p?.type!=='training')return'';return `<section class="card v83-mission-training"><span class="eyebrow">OBJETIVO DINÂMICO DA MISSÃO</span><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><button class="btn" data-action="v83-mission-training" data-id="${esc(run.id)}">Executar preparação • 90 min</button></section>`;}
  const renderTrainingV83Base=renderTraining;
  renderTraining=function(){if(!v81IsLeon())return renderTrainingV83Base();const m=v83EnsureState(),caps=v81LeonCaps().filter(x=>!v83IsPassive(x)),projects=Object.values(m.training.projects),mentors=v83VisibleMentors(),hasMission=!!v83MissionExercise();if(hasMission&&ui.v83TrainTab==='praticar')ui.v83TrainTab='missao';let body='';
    if(ui.v83TrainTab==='missao')body=v83MissionExercise()||'<div class="card"><p>Nenhum treino ligado a missão está pendente.</p></div>';
    if(ui.v83TrainTab==='praticar'){const trainableSkills=['Ninjutsu','Taijutsu','Controle de Chakra','Controle Espacial','Estratégia','Investigação','Armas Ninja','Kenjutsu/Kurai'];body=`<div class="v83-training-layout"><section class="card v83-training-form"><span class="eyebrow">DOMÍNIO DO QUE JÁ FOI ADQUIRIDO</span><h2>Prática dirigida</h2><p>Praticar melhora o histórico e pode satisfazer objetivos narrativos. Não cria uma técnica nova automaticamente.</p><label>Capacidade da ficha</label><select id="v83-practice-tech">${caps.map(x=>`<option value="${esc(x.id)}">${esc(V83_CATEGORY_LABEL[v83CapCategory(x)]||'')} — ${esc(x.nome)}</option>`).join('')}</select><label>Método e duração</label><select id="v83-practice-method"><option value="solo">Prática solo • 60 min</option><option value="dojo">Dojo supervisionado • 90 min</option><option value="mentor">Sessão com mentor • 180 min</option></select><button class="btn" data-action="v83-practice-owned">Iniciar prática</button></section><section class="card v83-training-form"><span class="eyebrow">DESENVOLVIMENTO DE REQUISITOS</span><h2>Treinar perícia</h2><p>Três sucessos em pelo menos nove horas concedem +1 no estado da campanha e recalculam o que pode ser aprendido.</p><label>Perícia</label><select id="v83-practice-skill">${trainableSkills.map(skill=>`<option value="${esc(skill)}">${esc(skill)} • atual ${v83SkillValue(skill)}${m.training.skillAdvances[skill]?` (+${m.training.skillAdvances[skill]} por campanha)`:''}</option>`).join('')}</select><button class="btn" data-action="v83-practice-skill">Treinar perícia • 180 min</button><div>${Object.entries(m.training.skillProjects).map(([skill,x])=>`<div class="v83-history-row"><b>${esc(skill)}</b><span>${x.successes}/3 sucessos • ${Math.round(x.minutes/60)}/9h</span></div>`).join('')}</div></section><section class="card"><h2>Últimos domínios trabalhados</h2>${Object.entries(m.training.mastery).slice(-10).reverse().map(([id,x])=>`<div class="v83-history-row"><b>${esc(v81LeonCaps().find(c=>c.id===id)?.nome||id)}</b><span>${Math.round(x.minutes/60)}h • ${x.successes} sucessos • ${x.failures} falhas</span></div>`).join('')||'<p class="muted">Nenhuma prática nova registrada.</p>'}</section></div>`;}
    if(ui.v83TrainTab==='projetos')body=`<div class="notice"><b>Regra de aquisição:</b> projeto + requisito + fonte/mentor + horas + prova final + Save Point. A enciclopédia nunca adiciona algo direto à ficha.</div><div class="v83-project-grid">${projects.map(p=>{const j=jutsuById(p.targetId),pct=Math.min(100,Math.round(p.progressMinutes/p.requiredMinutes*100));return `<article class="card v83-project"><span class="v83-state ${p.status==='CONCLUIDO'?'ok':p.status==='PRONTO_PARA_PROVA'?'ready':'training'}">${esc(p.status.replaceAll('_',' '))}</span><img src="${v82JutsuArt(j)}"><h3>${esc(p.name)}</h3><div class="v82-mastery"><i><b style="width:${pct}%"></b></i><span>${Math.round(p.progressMinutes/60)}/${Math.round(p.requiredMinutes/60)}h</span></div><p>${p.successes} sucessos • ${p.failures} falhas • fonte ${p.sourceValidated?'validada':'pendente'}</p>${p.status==='EM_TREINO'?`<select id="v83-mentor-${v75Norm(p.id)}"><option value="">Escolha o mentor</option>${v83MentorOptions(p)}</select><button class="btn" data-action="v83-project-session" data-id="${esc(p.id)}">Treinar • 180 min</button>`:''}${p.status==='PRONTO_PARA_PROVA'?`<button class="btn" data-action="v83-project-final" data-id="${esc(p.id)}">Fazer prova final • 60 min</button>`:''}</article>`;}).join('')||'<div class="card"><h3>Nenhum projeto aberto</h3><p>Abra a Enciclopédia, encontre uma técnica realmente adquirível e crie um projeto.</p><button class="btn" data-screen="enciclopedia">Abrir Enciclopédia</button></div>'}</div>`;
    if(ui.v83TrainTab==='mentores')body=`<div class="v83-mentor-grid">${mentors.map(x=>`<article class="card v83-mentor ${x.available?'available':'unavailable'}"><img src="${esc(x.image)}"><span class="v83-state ${x.available?'ok':'blocked'}">${x.available?'Disponível agora':'Fora de horário/local'}</span><h3>${esc(x.name)}</h3><p>${esc(x.specialty)}</p><small>${esc(x.source)} • ${esc(x.unlockedAt||'Descoberto em jogo')}</small></article>`).join('')}</div><div class="notice"><b>${Object.values(m.trainers).filter(x=>!x.discovered).length} contato(s) ainda oculto(s).</b> Missões, rumores e cenas podem revelar mentores adicionais sem expor sua identidade antes do gatilho.</div>`;
    if(ui.v83TrainTab==='dojo')body=`<div class="v82-dojo-grid"><article class="card"><img src="assets/original_v7/layout_dojo_1.png"><h3>Treino controlado</h3><p>O combate usa a mesma ficha, recursos, ativações, relógio e registro narrativo.</p><button class="btn" data-action="v83-start-dojo" data-id="normal">Entrar no dojo</button></article><article class="card"><img src="assets/enemies_v7/elite_espachim.svg"><h3>Instrutor experiente</h3><p>Teste requisitos e sequências de ativação em dificuldade maior.</p><button class="btn btn-danger" data-action="v83-start-dojo" data-id="elite">Desafiar</button></article></div>`;
    if(ui.v83TrainTab==='historico')body=`<div class="grid grid-2"><section class="card"><h2>Relógio da campanha</h2><div class="v83-big-clock">${v83ClockLabel(m.clock)}</div><p>${m.clock.totalMinutes} minutos transcorridos desde a migração V8.4.</p><p>Treinos, ações narrativas, viagens, missão e combate alimentam este mesmo relógio.</p></section><section class="card"><h2>Histórico de treino</h2>${m.training.history.slice(0,20).map(x=>`<p class="v82-history-line">${esc(x)}</p>`).join('')||'<p class="muted">Nenhum registro.</p>'}</section></div>`;
    const tabs=[...(hasMission?[['missao','Objetivo da missão']]:[]),['praticar','Praticar'],['projetos','Projetos'],['mentores','Mentores'],['dojo','Dojo'],['historico','Tempo e histórico']];screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">TREINAMENTO • ${v83ClockLabel(m.clock)}</span><h1>Treino conectado à campanha</h1><p>Cada sessão ocupa tempo, usa uma fonte válida, gera evento e pode alterar missão, mentor, condição ou narrativa.</p></div></div><div class="v82-tabs v82-tabs-big">${tabs.map(([id,l])=>`<button class="${ui.v83TrainTab===id?'active':''}" data-action="v83-train-tab" data-id="${id}">${l}</button>`).join('')}</div>${body}`;};

  function v83CatalogCard(j){const d=v83AcquireDecision(j),project=v83ProjectFor(j),m=j.mechanicsR27||{};return `<article class="card v83-catalog-card ${d.owned?'owned':d.trainable?'trainable':'blocked'}"><img src="${v82JutsuArt(j)}" alt="Arte de ${esc(j.name)}"><span class="v83-state ${d.owned?'ok':d.trainable?'ready':'blocked'}">${d.owned?'Na ficha':project?'Em projeto':d.trainable?'Pode iniciar treino':'Bloqueada'}</span><span class="badge">${esc(j.rank||'')}</span><h3>${esc(j.name)}</h3><p>${esc(j.description||'')}</p><div class="v82-tech-meta"><span>${esc(j.class||'')}</span><span>${esc(m.action||'Ação')}</span><span>Chakra ${j.chakraCost||0}</span><span>Vigor ${j.staminaCost||0}</span><span>${Number.isFinite(Number(m.rangeMeters))?`${m.rangeMeters} m`:'—'}</span><span>${esc(m.duration||'—')}</span><span>CD ${m.test?.cd??'—'}</span></div><small class="v83-requirement">${esc(d.reason)}</small><small class="v83-requirement">${esc(m.preActivation||'')}</small>${!d.owned&&!project?`<button class="btn" data-action="v83-start-project" data-id="${esc(j.id)}" ${d.trainable?'':`disabled title="${esc(d.reason)}"`}>Criar projeto de treino</button>`:project?'<button class="btn btn-secondary" data-screen="treino">Abrir projeto</button>':''}</article>`;}
  const renderEncyclopediaV83Base=renderEncyclopedia;
  renderEncyclopedia=function(){if(!v81IsLeon())return renderEncyclopediaV83Base();const m=v83EnsureState(),tab=ui.v83CodexTab,q=v75Norm(ui.v83CodexSearch),catalog=CAT.jutsus.filter(j=>!q||v75Norm(`${j.name} ${j.description} ${j.rank} ${j.class} ${j.elementReq}`).includes(q)),hidden=Object.values(m.trainers).filter(x=>!x.discovered).length;let body='';if(tab==='catalogo')body=`<div class="v82-toolbar"><input id="v83-codex-search" value="${esc(ui.v83CodexSearch)}" placeholder="Buscar na enciclopédia pública..."><span>${catalog.length} resultados</span></div><div class="notice"><b>Enciclopédia ≠ ficha.</b> Consultar uma entrada não concede posse. Somente itens marcados “Pode iniciar treino” passam pelo projeto, mentor, tempo, prova e Save Point.</div><div class="v82-tech-grid v83-catalog-grid">${catalog.slice(0,ui.v83CodexLimit).map(v83CatalogCard).join('')}</div>${catalog.length>ui.v83CodexLimit?'<button class="btn btn-secondary v83-load-more" data-action="v83-codex-more">Mostrar mais</button>':''}`;
    if(tab==='arquivo')body=`<div class="grid grid-2"><section class="card"><h2>Registro mimético</h2><p>Técnicas observadas ou copiadas permanecem no arquivo com estado próprio. Bloqueio por rank ou requisito não apaga o registro.</p>${m.copies.map(x=>`<div class="v83-history-row"><b>${esc(x.name||x.id)}</b><span>${esc(x.state||'OBSERVACAO_INCOMPLETA')}</span></div>`).join('')||'<p class="muted">Nenhuma cópia registrada neste Save Point.</p>'}</section><section class="card"><h2>Estados aceitos</h2>${['COPIADO_ATIVO','COPIADO_BLOQUEADO_POR_RANK','COPIADO_BLOQUEADO_POR_REQUISITO','OBSERVACAO_INCOMPLETA','EM_TREINO','INDISPONIVEL'].map(x=>`<div class="v83-history-row"><b>${x}</b><span>Execução validada pelo estado</span></div>`).join('')}</section></div>`;
    if(tab==='mestres')body=`<div class="v83-mentor-grid">${v83VisibleMentors().map(x=>`<article class="card v83-mentor"><img src="${esc(x.image)}"><h3>${esc(x.name)}</h3><p>${esc(x.specialty)}</p><small>${esc(x.source)}</small></article>`).join('')}</div><div class="notice">${hidden} mentor(es) potencial(is) permanecem ocultos até uma missão, rumor, viagem ou cena disparar o encontro.</div>`;
    if(tab==='vinculos')body=v82RenderLeonCodex(ui.v82CodexTab==='kurai'?'kurai':'visao');
    if(tab==='regras')body=`<div class="v82-rules-grid">${(V83.masterDirectives||[]).map((x,i)=>`<article class="card"><h3>${i+1}. Controle integrado</h3><p>${esc(x)}</p></article>`).join('')}<article class="card"><h3>Fontes carregadas</h3><p>Controle Mestre TERION v1, State Schema v1, System Prompt TERION e base normalizada estão incluídos em DADOS_MESTRES/CONTROLE_TERION.</p></article></div>`;
    screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">ENCICLOPÉDIA • REFERÊNCIA, NÃO POSSE</span><h1>Catálogo e regras do mundo</h1><p>Conteúdo não adquirido fica aqui; a ficha mostra somente o que pertence ao personagem.</p></div></div><div class="v82-tabs v82-tabs-big">${[['catalogo','Catálogo'],['arquivo','Arquivo mimético'],['mestres','Mestres e fontes'],['vinculos','Projeto Kosmo'],['regras','Regras integradas']].map(([id,l])=>`<button class="${tab===id?'active':''}" data-action="v83-codex-tab" data-id="${id}">${l}</button>`).join('')}</div><div class="v82-codex-body">${body}</div>`;};

  function v83MissionRecord(run){const m=v83EnsureState(),mission=missionById(run?.id)||{};if(!run)return null;return m.missions[run.id]=m.missions[run.id]||{id:run.id,name:mission.name||run.id,status:'ACTIVE',startedAt:v83ClockLabel(m.clock),branches:[],pending:null};}
  function v83MissionAccess(mission){if(!mission)return {ok:false,reason:'Missão inexistente'};if(!v81IsLeon())return {ok:missionAvailable(mission),reason:'Requisitos gerais da missão'};if(!['TASK','D','C'].includes(String(mission.rank||'')))return {ok:false,reason:`Rank ${mission.rank} acima da escala atual de Leon`};if(ui.currentMission)return {ok:false,reason:'Já existe uma missão ativa'};return {ok:true,reason:'Compatível com Genin/TERION; custo genérico de Vigor não se aplica a Leon'};}
  const renderMissionsV83Base=renderMissions;
