  function v83CreateMissionBranch(choice){const run=ui.currentMission;if(!run||ui.battle)return null;const rec=v83MissionRecord(run);if(!rec||rec.pending||rec.status!=='ACTIVE')return null;const types=['combat','training','mentor','investigation'],type=types[v83Hash(`${run.id}:${run.stage}:${choice}:${rec.branches.length}`)%types.length],defs={combat:['Confronto emergente','A situação mudou: uma oposição hostil entrou no caminho da missão.'],training:['Preparação de campo','Uma etapa da missão exige prática ou ajuste técnico antes de continuar.'],mentor:['Contato inesperado','A missão criou uma oportunidade de conhecer uma nova fonte de treinamento.'],investigation:['Pista não prevista','Uma informação nova abriu uma rota de investigação que não existia no briefing.']};rec.pending={id:`branch-${Date.now()}`,type,title:defs[type][0],description:defs[type][1],createdAt:v83ClockLabel(v83EnsureState().clock),status:'PENDING'};rec.branches.push(v83Copy(rec.pending));v83Commit('mission_branch_created',{label:`Missão gerou: ${rec.pending.title}`,missionId:run.id,branchType:type},0);return rec.pending;}
