  function v84IntegrateVisualDraft(){
    const m=v84EnsureMaster(),visual=ui.aiDraft?.visual;if(!m||!visual||typeof visual!=='object')return;
    const signature=JSON.stringify(visual);if(!signature||signature===m.visual.lastDraftSignature)return;
    m.visual.lastDraftSignature=signature;
    if(V84.battlefields?.[visual.battlefieldPreset])m.battlefield.preset=visual.battlefieldPreset;
    const coordinateHazards=(Array.isArray(visual.hazards)?visual.hazards:[]).filter(x=>/^\d{1,2},\d{1,2}$/.test(String(x)));
    if(coordinateHazards.length)m.battlefield.hazards=[...new Set([...m.battlefield.hazards,...coordinateHazards])];
    m.scene.visualHazards=(Array.isArray(visual.hazards)?visual.hazards:[]).map(String).slice(0,8);
    const allowed=new Map([['player',{name:state.character?.name||'Shinobi',kind:'player',image:state.character?.avatar||VIS84.entities?.leon}]]);
    if(v81IsLeon()&&state.masterV83?.active?.suirinPresent)allowed.set('suirin',{name:'Suirin',kind:'ally',image:VIS84.entities?.suirin});
    if(ui.battle)allowed.set('enemy',{name:ui.battle.enemy?.name||'Oposição',kind:'enemy',image:v84Visual('npcsByName','',ui.battle.enemy?.name,'assets/enemies_v7/elite_espachim.svg')});
    for(const n of (WORLD84.npcs||[]).filter(x=>x.present))allowed.set(n.id,{name:n.name,kind:'ally',image:v84NpcArt(n)});
    for(const pos of (Array.isArray(visual.tokenPositions)?visual.tokenPositions:[])){
      const def=allowed.get(String(pos.id));if(!def)continue;
      const x=Math.max(0,Math.min(11,Math.round(Number(pos.x)||0))),y=Math.max(0,Math.min(11,Math.round(Number(pos.y)||0)));
      let token=m.battlefield.tokens.find(t=>t.id===String(pos.id));
      if(!token){token={id:String(pos.id),...def,x,y};m.battlefield.tokens.push(token);}else{token.x=x;token.y=y;}
    }
    if(ui.aiDraft?.resolution?.type==='combat'||(visual.tokenPositions||[]).length)m.visual.battlefieldVisible=true;
  }

