  function v84KnowledgeMeta(type,x){
    if(type==='techniques')return `${x.rank||x.rank_origem||'—'} • ${x.tier_v68||x.categoria||x.fonteOuNatureza||'Técnica'} • ${x.categoria||'Técnica'} • ${x.familia_natureza||x.fonteOuNatureza||'Chakra'} • Custo ${x.custo??x.custoChakra??'não confirmado'} • CD ${x.cd_referencia??x.testePadrao?.CD??'não confirmada'}`;
    if(type==='items')return `${x.raridade||'—'} • ${x.tipo||'Item'} • ${x.efeitoOperacional||'Efeito conforme registro'}`;
    if(type==='missions')return `Rank ${x.rank||'—'} • ${x.premissa||''}`;
    if(type==='arcs')return `${x.era||'Era não confirmada'} • ${x.statusInicial||'Registro'}`;
    if(type==='campaigns')return `${(x.arcos||[]).length} arcos • ${x.objetivo||''}`;
    if(type==='factions')return `${x.liderNoInicio||'Liderança não confirmada'} • ${(x.objetivos||[]).join(' • ')}`;
    return `${x.tipo||'Local'} • ${(x.riscos||[]).join(' • ')}`;
  }
  function r39SemanticKnowledgeFallback(type,x){
    const key=v84NormKey(`${x?.nome||x?.name||''} ${x?.familia_natureza||x?.fonteOuNatureza||''} ${x?.categoria||x?.tipo||''}`);
    if(type==='techniques'){
      const old=(CAT.jutsus||[]).find(j=>v84NormKey(j.name||j.nome)===v84NormKey(x?.nome||x?.name));
      const direct=old&&(VIS84.techniques?.[old.id]||VIS84.knowledgeTechniques?.[old.id]);if(direct)return direct;
      const families=[
        [/(katon|fogo|fire)/,'assets/v841/techniques/katon_housenka_no_jutsu.svg'],
        [/(suiton|agua|water)/,'assets/v841/techniques/suiton_daibakufu_no_jutsu.svg'],
        [/(raiton|relamp|lightning)/,'assets/v841/techniques/raiton_chidori.svg'],
        [/(fuuton|vento|wind)/,'assets/v841/techniques/fuuton_juuha_shou.svg'],
        [/(doton|terra|earth)/,'assets/v841/techniques/doton_doryuu_jouheki.svg'],
        [/(genjutsu|ilus|magen)/,'assets/v841/techniques/magen_narakumi_no_jutsu_i.svg'],
        [/(clone|bunshin)/,'assets/v841/techniques/kage_bunshin_no_jutsu_i.svg'],
        [/(kugutsu|marion)/,'assets/v841/techniques/kugutsu_sakura_no_mai.svg'],
        [/(taijutsu|juuken|chute|soco|kick|punch)/,'assets/v841/techniques/dynamic_kick.svg'],
        [/(rasengan)/,'assets/v841/techniques/rasengan.svg']
      ];for(const [re,img] of families)if(re.test(key))return img;
      return 'assets/ui/media-pendente.svg';
    }
    if(type==='items'){
      const old=[...(LIV.itens||[]),...(V7.items||[])].find(i=>v84NormKey(i.nome||i.name)===v84NormKey(x?.nome||x?.name));
      return (old&&(VIS84.items?.[old.id]||VIS84.knowledgeItems?.[old.id]))||VIS84.knowledgeItems?.[x?.id]||VIS84.items?.[x?.id]||VIS84.equipment?.[x?.id]||'assets/ui/media-pendente.svg';
    }
    return 'assets/ui/media-pendente.svg';
  }
  function v84KnowledgeImage(type,x){const maps={techniques:'knowledgeTechniques',items:'knowledgeItems',missions:'missions',arcs:'arcs',campaigns:'campaigns',factions:'factions',locations:'locations'};return VIS84[maps[type]]?.[x.id]||VIS84.events?.[x.id]||r39SemanticKnowledgeFallback(type,x);}
