      const side=screen.querySelector('.shop-side-v74 .card,.shop-side .card');if(side){const h=side.querySelector('h3');if(h)h.textContent='Ichiraku Ramen';side.insertAdjacentHTML('afterbegin',`<img src="assets/r25/ichiraku/exterior.png" alt="Ichiraku Ramen" style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:10px;margin-bottom:10px"><div class="v84-stage-actors"><button data-action="v84-open-npc" data-id="R25_CANON_TEUCHI"><img src="assets/r25/ichiraku/teuchi.png" alt="Teuchi"><span><b>Teuchi</b><small>Dono • rotina viva</small></span></button><button data-action="v84-open-npc" data-id="R25_CANON_AYAME"><img src="assets/r25/ichiraku/ayame.png" alt="Ayame"><span><b>Ayame</b><small>Atendimento • rotina viva</small></span></button></div>`);}
