  const createCharacterR25CoreBase=createCharacter;
  createCharacter=function(){const d=getCreationDraft(),core=JSON.parse(JSON.stringify(d.terionCore||r25CoreDefaults()));const result=createCharacterR25CoreBase();if(state.character&&!state.character.privateCharacter){state.character.terionCore=core;state.character.baseAttributes={...r25LegacyFromCoreValues(core)};recalc(state.character,true);state.character.rulesContract={...(state.character.rulesContract||{}),engine:'TERION 2D10',coreAttributes:['Corpo','Mente','Espírito','Técnica'],legacyCompatibility:'derived-only'};saveState(true);render();}return result;};
