  window.__NARUTO_R25_CORE__={version:'R25.2-TERION-CORE-2026-08-12',draft:()=>getCreationDraft().terionCore,spent:()=>r25CoreSpent(getCreationDraft()),character:()=>state.character?.terionCore||null,resources:()=>({core:state.character?.terionCore||null,hp:state.character?.maxHp,chakra:state.character?.maxChakra,vigor:state.character?.maxStamina})};
