    const after={hp:Number(c.hp||0),chakra:Number(c.chakra||0),stamina:Number(c.stamina||0),ryo:Number(c.ryo||0),rep:Number(state.story.reputation||0),xp:Number(c.xp||0),level:Number(c.level||1)};
