    const applied={...e,addConditions:adds,removeConditions:rems};result.appliedEffects=applied;result.effectMeta={...meta,sourceType:source,reason,appliedBy:'R27_ENGINE'};result.effects={xp:0,ryo:0,hp:0,chakra:0,stamina:0,reputacao:0,addConditions:[],removeConditions:[]};result.efeitos=result.effects;
