  function r27EnemyArtForOpponent(opp={}){
    const name=String(opp.name||opp.nome||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    const pool=V7.enemies||[];
    let hit=pool.find(e=>String(e.nome||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()===name);
    if(!hit&&/nukenin/.test(name)){for(const [word,id] of [['folha','nukenin_folha'],['areia','nukenin_areia'],['nevoa','nukenin_nevoa'],['nuvem','nukenin_nuvem'],['pedra','nukenin_pedra'],['som','nukenin_som'],['chuva','nukenin_chuva']])if(name.includes(word)){hit=pool.find(e=>e.id===id);break;}hit=hit||pool.find(e=>e.id==='nukenin_assassino');}
    if(!hit&&/bandido/.test(name))hit=pool.find(e=>e.id==='bandido_estrada')||pool.find(e=>e.id==='bandido_batedor');
    if(!hit&&/samurai/.test(name))hit=pool.find(e=>e.id==='samurai_hostil');
    if(!hit&&/anbu/.test(name))hit=pool.find(e=>e.id==='anbu_renegado');
    if(!hit&&/mercen/.test(name))hit=pool.find(e=>e.id==='mercenario');
    return opp.art||opp.image||opp.imagem||hit?.art||'assets/r27/enemies/nukenin_assassino.jpg';
  }

