  function r27SetBattleOpponents(b,opponents=[]){if(!b||!opponents.length)return;const dims=r27BattleDims(b),used=new Set([`${b.playerPos?.x??1},${b.playerPos?.y??1}`]);b.enemies=opponents.map((o,i)=>r27NormalizeOpponent(o,i,b));b.enemyPositions={};for(let i=0;i<b.enemies.length;i++){const o=opponents[i]||{},pos=o.position||o.posicao||{},fallback={x:Math.max(0,dims.w-2-(i%dims.w)),y:Math.min(dims.h-1,1+Math.floor(i/Math.max(1,dims.w-2)))};let x=clamp(Number.isFinite(Number(pos.x))?Number(pos.x):fallback.x,0,dims.w-1),y=clamp(Number.isFinite(Number(pos.y))?Number(pos.y):fallback.y,0,dims.h-1),guard=0;while(used.has(`${x},${y}`)&&guard++<dims.w*dims.h){x=(x-1+dims.w)%dims.w;if(x===b.playerPos?.x&&y===b.playerPos?.y)y=(y+1)%dims.h;}used.add(`${x},${y}`);b.enemyPositions[b.enemies[i].id]={x,y};}b.selectedEnemyId=b.enemies[0].id;r27SyncBattleTarget(b);b.r27IntentLog=[];}
