  function r27PathStep(b,from,to,selfId,maxSteps=1,away=false){const dims=r27BattleDims(b);let p={x:from.x,y:from.y};for(let n=0;n<maxSteps;n++){const cand=[{x:p.x+1,y:p.y},{x:p.x-1,y:p.y},{x:p.x,y:p.y+1},{x:p.x,y:p.y-1}].filter(q=>q.x>=0&&q.y>=0&&q.x<dims.w&&q.y<dims.h&&!r27CellBlocked(b,q.x,q.y,selfId));if(!cand.length)break;cand.sort((a,c)=>{const da=gridDistance(a,to),dc=gridDistance(c,to);return away?dc-da:da-dc;});const best=cand[0];if(!away&&gridDistance(best,to)>=gridDistance(p,to)&&gridDistance(p,to)<=1)break;p=best;}return p;}
