    run.branches=Array.isArray(run.branches)?run.branches:[];const branchType=choice.combat?'combat':['investigation','training','mentor','combat'][(Number(index)+run.stage)%4],branch={id:`${run.id}-r27-${run.branches.length+1}`,type:branchType,label:branchType==='combat'?'Possível confronto':branchType==='mentor'?'Contato/mentor':branchType==='training'?'Preparação/treino':'Investigação',createdAt:Date.now(),resolved:false};run.branches.push(branch);
    state.r27.missionLog.push({missionId:run.id,stage:run.stage,choice:choice.label,success,total,cd,branch:branchType});state.r27.missionLog=state.r27.missionLog.slice(-100);
