      if(confirmed){branch.resolved=true;branch.opponents=opponents;saveState(true);if(isLeon){v8StartLeonBattle(false);}else startBattle(null,mission);if(ui.battle){const opp=opponents[0]||{};ui.battle.r27ConfirmedByNarrative=true;ui.battle.r27Opponents=opponents;ui.battle.linkedMissionId=run.id;ui.battle.v83Source='mission';ui.battle.r27OpponentSource='AI_STRUCTURED_VALIDATED';if(ui.battle.enemy){ui.battle.enemy.name=String(opp.name||opp.nome||ui.battle.enemy.name||'Oposição');ui.battle.enemy.art=r27EnemyArtForOpponent(opp);const hp=Number(opp.hp??opp.pv??opp.maxHp??opp.pvMax);if(Number.isFinite(hp)&&hp>0){ui.battle.enemy.hp=hp;ui.battle.enemy.maxHp=Number(opp.maxHp??opp.pvMax??hp)||hp;}const ch=Number(opp.chakra??opp.chakraAtual??opp.maxChakra);if(Number.isFinite(ch)&&ch>=0){ui.battle.enemy.chakra=ch;ui.battle.enemy.maxChakra=Number(opp.maxChakra??opp.chakraMax??ch)||ch;}const def=Number(opp.defense??opp.defesa);if(Number.isFinite(def))ui.battle.enemy.r27Defense=def;ui.battle.enemy.objective=opp.objective||opp.objetivo||'hostilidade confirmada pela narrativa';}const pos=opp.position||opp.posicao;if(pos&&Number.isFinite(Number(pos.x))&&Number.isFinite(Number(pos.y)))ui.battle.enemyPos={x:clamp(Number(pos.x),0,11),y:clamp(Number(pos.y),0,11)};r27SetBattleOpponents(ui.battle,opponents);}saveState(true);render();return;}
      ui.missionLog.unshift({text:'R27: a IA não confirmou inimigo hostil concreto; combate bloqueado.',type:'info'});run.narrative+=`\n\nRESULTADO DO GATE DE COMBATE\n\nA escolha sugeria confronto, mas não existe oponente hostil concreto confirmado no estado. A missão NÃO abre a tela tática; a próxima decisão continua na narrativa a partir deste mesmo estado.`;
