    const generic=['Nukenin da Folha','Bandido da Estrada','Mercenário'];const count=ch.type==='reinforcements'?2:ch.type==='boss'||ch.type==='duel1v1'?1:2;return generic.slice(0,count).map((name,i)=>({name,hp:ch.type==='boss'?34:18+i*3,chakra:ch.type==='boss'?18:8,defense:ch.type==='boss'?14:11+i,level:ch.type==='boss'?5:2+i,objective:ch.type==='protect'?'atingir o protegido':'impedir o objetivo'}));
