  function r27StoryStart(chId){const sm=r27StoryEnsure(),ch=r27StoryChapters().find(x=>x.id===chId);if(!ch)return;if(ch.index>sm.chapter&&!sm.completed[ch.id])return toast('Capítulo ainda bloqueado.','error');sm.active={chapterId:ch.id,type:ch.type,progress:0,successes:0,failures:0,pressure:0,clues:0,advantage:0,usedChoices:[],lastResult:'',protectHp:12,maxProtectHp:12,targetRounds:ch.targetRounds,minChakra:ch.minChakra,startedAt:v83ClockLabel(v83EnsureState().clock)};v83Commit('story_chapter_start',{label:`História iniciada: ${ch.title}`,chapterId:ch.id,type:ch.type},10);if(ch.type==='team3v3'){const duel=r27DuelEnsure();duel.playerTeam=sm.unlockedNpcIds.slice(0,3);duel.aiTeam=[];const ids=ch.participants.map(x=>x.id).filter(id=>!duel.playerTeam.includes(id));duel.aiTeam=ids.slice(0,3);if(duel.aiTeam.length<3)r27DuelAutoAI();ui.screen='duelo-r27';saveState(true);render();return;}if(['survive','protect','boss','reinforcements','chakra','duel1v1','defeat'].includes(ch.type)){if(state.character?.privateCharacter==='leon')v8StartLeonBattle(ch.type==='boss');else startBattle(ch.type==='boss'?'elite_nukenin':'bandido_batedor');if(ui.battle){r27SetBattleOpponents(ui.battle,r27StoryEnemySpecs(ch));ui.battle.r27StoryChallenge={chapterId:ch.id,type:ch.type,targetRounds:ch.targetRounds,protectHp:12,maxProtectHp:12,minChakra:ch.minChakra,reinforcementsSpawned:false};ui.battle.v83Source='story';ui.screen='combate';}saveState(true);render();return;}ui.screen='historia-r27';saveState(true);render();}
  function r36StoryChance(bonus,cd){let ok=0,total=0;for(let h=1;h<=10;h++)for(let d=1;d<=10;d++){total++;if(!(h===1&&d===1)&&h+d+bonus>=cd)ok++;}return Math.round(ok/total*100);}
  function r27StoryChoice(choiceId){
    const sm=r27StoryEnsure(),active=sm.active,ch=r27StoryChapters().find(x=>x.id===active?.chapterId);if(!active||!ch)return;
    let choice=(ch.choices||[]).find(x=>x.id===choiceId);if(!choice&&['cautela','direta','social'].includes(choiceId))choice=(ch.choices||[])[['cautela','direta','social'].indexOf(choiceId)];if(!choice)return toast('Escolha inexistente neste capítulo.','error');
    active.usedChoices=Array.isArray(active.usedChoices)?active.usedChoices:[];if(active.usedChoices.includes(choice.id))return toast('Essa abordagem já foi usada neste capítulo. Escolha outra consequência real.','error');active.usedChoices.push(choice.id);
    const c=state.character,bonus=c.privateCharacter==='leon'?Number(c.specialProfile?.skillRatings?.[choice.skill]||c.specialProfile?.coreAttributes?.[choice.attr]||3):skillTotal(LIV.pericias?.find(x=>v75Norm(x.nome||x.id).includes(v75Norm(choice.skill)))?.id||'procurar'),r=rollTerion2d10();
    active.pressure=Number(active.pressure||0);active.clues=Number(active.clues||0);active.advantage=Number(active.advantage||0);
    const cd=Math.max(8,Number(choice.cd||12)+active.pressure-active.clues-active.advantage),total=r.total+bonus,ok=r.total>3&&total>=cd;active.progress++;active[ok?'successes':'failures']++;
    if(ok){if(choice.reward==='clue')active.clues++;else if(choice.reward==='advantage')active.advantage++;else state.story.reputation=Number(state.story.reputation||0)+1;}
    else{active.pressure++;if(choice.risk==='alto')c.hp=Math.max(1,c.hp-2);else if(choice.risk==='médio')c.chakra=Math.max(0,c.chakra-1);else c.hp=Math.max(1,c.hp-1);}
    active.lastResult=`${choice.label}: ${ok?'SUCESSO':'FALHA'} • 2D10 ${r.rolls.join('+')} + ${bonus} = ${total} vs CD ${cd}. ${ok?'A posição da equipe melhora e o próximo teste pode ficar mais favorável.':'A pressão aumenta e há consequência real no estado.'}`;
    v83Commit('story_choice',{label:`${ch.title}: ${choice.label} • ${ok?'sucesso':'falha'}`,chapterId:ch.id,choiceId,roll:r.rolls,total,cd,success:ok,pressure:active.pressure,clues:active.clues,advantage:active.advantage},Number(choice.minutes||30));
    if(active.successes>=2&&active.progress>=3)r27StoryComplete(ch,{successes:active.successes,failures:active.failures,pressure:active.pressure,clues:active.clues,advantage:active.advantage});
    else if(active.failures>=3){sm.history.push({chapter:ch.id,result:'FALHA',at:v83ClockLabel(v83EnsureState().clock),pressure:active.pressure});sm.active=null;v83SavePoint?.(`História falhou: ${ch.title}`,[{chapterId:ch.id,failures:active.failures,pressure:active.pressure}]);}
    saveState(true);render();
  }
  function r27StoryBattleTick(b){const sc=b?.r27StoryChallenge;if(!sc||b.over)return;const ch=r27StoryChapters().find(x=>x.id===sc.chapterId);if(!ch)return;if(sc.type==='protect'&&b.turn==='enemy'){const dmg=rand(1,3);sc.protectHp=Math.max(0,Number(sc.protectHp||12)-dmg);battleLog(`O protegido sofre ${dmg} dano colateral • ${sc.protectHp}/${sc.maxProtectHp}.`,sc.protectHp>0?'info':'bad');if(sc.protectHp<=0){if(state.character?.privateCharacter==='leon')v8LeonFinish(false);else finishBattle(false);return;}}if(sc.type==='reinforcements'&&Number(b.round||b.turn||1)>=3&&!sc.reinforcementsSpawned){sc.reinforcementsSpawned=true;const extra={name:'Reforço Nukenin',hp:20,chakra:9,defense:12,level:3,objective:'reforçar a oposição'};const current=r27ActiveEnemies(b).map(e=>({...e,position:b.enemyPositions?.[e.id]}));current.push(extra);r27SetBattleOpponents(b,current);battleLog('Reforços chegaram ao campo.', 'bad');}if(sc.type==='survive'&&Number(b.round||b.turn||1)>=sc.targetRounds){r27StoryComplete(ch,{survivedRounds:sc.targetRounds});b.over=true;b.result='story_survived';ui.battle=null;ui.screen='historia-r27';render();}}
  const advanceBattleTurnR27StoryBase=advanceBattleTurn;
