  finishBattle=function(win){const b=ui.battle,sc=b?.r27StoryChallenge,ch=sc?r27StoryChapters().find(x=>x.id===sc.chapterId):null;if(win&&sc&&ch){if(sc.type==='chakra'&&Number(state.character.chakra||0)<sc.minChakra){battleLog(`Objetivo de Chakra falhou: restaram ${state.character.chakra}, mínimo ${sc.minChakra}.`,'bad');return finishBattleR27StoryBase(false);}r27StoryComplete(ch,{battle:true,round:b.round||b.turn||1,protectHp:sc.protectHp,chakra:state.character.chakra});}return finishBattleR27StoryBase(win);};
