  function r27RenderStory(){const sm=r27StoryEnsure(),chapters=r27StoryChapters(),active=sm.active,ch=chapters.find(x=>x.id===active?.chapterId);if(active&&ch&&!['team3v3','survive','protect','boss','reinforcements','chakra','duel1v1','defeat'].includes(ch.type)){screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">MODO HISTÓRIA • CAPÍTULO ${ch.index}</span><h1>${esc(ch.title)}</h1><p>${esc(ch.premise)}</p></div><button class="btn btn-secondary" data-action="r27-story-abandon">Abandonar capítulo</button></div><section class="card"><h2>Objetivo: ${esc(ch.type)}</h2><p>Local: ${esc(ch.location||'definido pela cena')} • Progresso ${active.progress}/3 • Sucessos ${active.successes}/2 • Falhas ${active.failures}/3.</p><p>Cada escolha tem perícia, CD, risco, tempo e efeito próprios. Falha aumenta Pressão e pode consumir PV/Chakra; Pistas/Vantagem reduzem CDs futuras.</p>${active.lastResult?`<div class="notice ${/FALHA/.test(active.lastResult)?'warn':'success'}">${esc(active.lastResult)}</div>`:''}<div class="r34-mission-state"><span>Pressão <b>${Number(active.pressure||0)}</b></span><span>Pistas <b>${Number(active.clues||0)}</b></span><span>Vantagem <b>${Number(active.advantage||0)}</b></span></div><div class="grid grid-3">${(ch.choices||[]).map(choice=>{const c=state.character,bonus=c.privateCharacter==='leon'?Number(c.specialProfile?.skillRatings?.[choice.skill]||c.specialProfile?.coreAttributes?.[choice.attr]||3):skillTotal(LIV.pericias?.find(x=>v75Norm(x.nome||x.id).includes(v75Norm(choice.skill)))?.id||'procurar'),cd=Math.max(8,Number(choice.cd||12)+Number(active.pressure||0)-Number(active.clues||0)-Number(active.advantage||0));return `<button class="choice-card" data-action="r27-story-choice" data-id="${esc(choice.id)}" ${active.usedChoices?.includes(choice.id)?'disabled title="Escolha já usada"':''}><b>${esc(choice.label)}</b><small>${esc(choice.text)}</small><span class="r33-test">${esc(choice.skill)} +${bonus} • CD ${cd} • ${r36StoryChance(bonus,cd)}% • risco ${esc(choice.risk)} • ${choice.minutes} min</span></button>`;}).join('')}</div></section>`;return;}screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">HISTÓRIA • NARUTO ARENA COMO REFERÊNCIA DE PROGRESSÃO</span><h1>Campanha e desbloqueios</h1><p>26 capítulos canônicos possuem objetivos diferentes; completar capítulos desbloqueia personagens para o modo 3×3 e salva automaticamente.</p></div></div><section class="r27-story-grid">${chapters.map(ch=>{const done=!!sm.completed[ch.id],locked=ch.index>sm.chapter&&!done;return `<article class="card ${done?'completed':''}"><span class="badge">${esc(ch.arcId)} • ${esc(ch.type)}</span><h3>${ch.index}. ${esc(ch.title)}</h3><p>${esc(ch.premise)}</p><small>${esc(ch.location||'')}</small><p>${ch.rewardNpc?`Desbloqueio: <b>${esc(ch.rewardNpc.nome)}</b>`:'Recompensa de campanha'}</p><button class="btn" data-action="r27-story-start" data-id="${ch.id}" ${locked?'disabled':''}>${done?'Rejogar':locked?'Bloqueado':'Iniciar'}</button></article>`;}).join('')}</section>`;}
  const renderR27StoryBase=render;
  render=function(){if(ui.screen==='historia-r27'){renderChrome();r27RenderStory();return;}return renderR27StoryBase();};
  const renderChromeR27StoryBase=renderChrome;
  renderChrome=function(){renderChromeR27StoryBase();if(!state.character)return;const play=[...nav.querySelectorAll('.v82-nav-group')].find(g=>/JOGAR/i.test(g.textContent||''))||nav;if(!nav.querySelector('[data-screen="historia-r27"]'))play.insertAdjacentHTML('beforeend',`<button class="nav-button ${ui.screen==='historia-r27'?'active':''}" data-screen="historia-r27"><span>📖</span>História</button>`);};
  document.addEventListener('click',e=>{const b=e.target?.closest?.('[data-action^="r27-story-"]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='r27-story-start')r27StoryStart(id);else if(a==='r27-story-choice')r27StoryChoice(id);else if(a==='r27-story-abandon'){r27StoryEnsure().active=null;saveState(true);render();}});

  // R27_TEAM_DUEL — álbum, filtros, 3 slots, IA adversária e combate 3x3 persistente.
  const R27_BORUTO_NAMES=new Set(['Boruto Uzumaki','Sarada Uchiha','Mitsuki','Kawaki','Himawari Uzumaki','Sumire Kakei','Shikadai Nara','Inojin Yamanaka','Chōchō Akimichi','Chocho Akimichi','Metal Lee','Wasabi Izuno','Denki Kaminarimon','Iwabe Yuino']);
  const R27_REANIMATED_NAMES=new Set(['Hashirama Senju','Tobirama Senju','Hiruzen Sarutobi','Minato Namikaze','Mū','Gengetsu Hōzuki','Terceiro Raikage','Rasa','Madara Uchiha']);
  function r27DuelEnsure(){r27Ensure();state.r27.duel=state.r27.duel||{playerTeam:[],aiTeam:[],filter:'TODOS',battle:null,unlocked:[],history:[]};return state.r27.duel;}
  function r27DuelEra(n){if(R27_BORUTO_NAMES.has(n.name))return'BORUTO';if(R27_REANIMATED_NAMES.has(n.name))return'REANIMADOS';const id=Number(String(n.id||'').match(/(\d+)/)?.[1]||999);return id<=90?'ORIGINAL':'SHIPPUDEN';}
  function r27DuelRoster(){const seen=new Set();return (WORLD84.npcs||[]).filter(n=>n.canon&&n.name&&!/bijū|besta|animal|cão|sapo|serpente|lesma/i.test(`${n.role||''} ${n.affiliation||''}`)).filter(n=>{const k=v75Norm(n.name);if(seen.has(k))return false;seen.add(k);return true;}).map(n=>({...n,r27Era:r27DuelEra(n),art:v84NpcArt(n)}));}
  function r27DuelSelect(id){const d=r27DuelEnsure(),sm=r27StoryEnsure();if(d.battle)return;if(!sm.unlockedNpcIds.includes(id))return toast('Personagem ainda não desbloqueado no Modo História.','error');const team=d.playerTeam,idx=team.indexOf(id);if(idx>=0)team.splice(idx,1);else if(team.length<3)team.push(id);else return toast('A equipe já tem 3 integrantes. Remova um antes de adicionar outro.','error');saveState(true);render();}
  function r27DuelAutoAI(){const d=r27DuelEnsure(),pool=r27DuelRoster().filter(n=>!d.playerTeam.includes(n.id));d.aiTeam=[];while(d.aiTeam.length<3&&pool.length){const i=Math.floor(Math.random()*pool.length);d.aiTeam.push(pool.splice(i,1)[0].id);}saveState(true);render();}
  function r27DuelFighter(n,side,i){const tier=Math.max(1,Number(n?.tier||1)),hp=14+tier*6,ch=8+tier*4;return {id:n.id,name:n.name,side,index:i,art:v84NpcArt(n),tier,hp,maxHp:hp,chakra:ch,maxChakra:ch,defense:10+tier,attack:2+tier,technique:3+tier,guard:0,conditions:[],signature:(n.signatureTechniques||[]).slice(0,4)};}
  function r27StartDuel(){const d=r27DuelEnsure();if(d.playerTeam.length!==3)return toast('Escolha exatamente 3 personagens para sua equipe.','error');if(d.aiTeam.length!==3)r27DuelAutoAI();if(d.aiTeam.length!==3)return toast('Não foi possível montar a equipe da IA.','error');const byId=id=>(WORLD84.npcs||[]).find(n=>n.id===id);d.battle={round:1,turn:'PLAYER',activeIndex:0,targetIndex:0,player:d.playerTeam.map((id,i)=>r27DuelFighter(byId(id),'PLAYER',i)),ai:d.aiTeam.map((id,i)=>r27DuelFighter(byId(id),'AI',i)),log:[],over:false,winner:''};d.battle.log.unshift('Duelo 3×3 iniciado. Cada lutador mantém PV, Chakra, defesa e estado próprios.');saveState(true);render();}
  function r27DuelAlive(list){return list.filter(x=>x.hp>0);}
  function r27DuelCurrent(b){let f=b.player[b.activeIndex];if(!f||f.hp<=0){const i=b.player.findIndex(x=>x.hp>0);b.activeIndex=Math.max(0,i);f=b.player[b.activeIndex];}return f;}
  function r27DuelTarget(b){let t=b.ai[b.targetIndex];if(!t||t.hp<=0){const i=b.ai.findIndex(x=>x.hp>0);b.targetIndex=Math.max(0,i);t=b.ai[b.targetIndex];}return t;}
  function r27DuelRoll(attacker,target,kind='attack'){const r=r25Duo(),bonus=kind==='technique'?attacker.technique:attacker.attack,total=r.total+bonus,ca=target.defense+Number(target.guard||0),hit=!(r.hope===1&&r.doom===1)&&total>=ca;let damage=0;if(hit){damage=Math.max(1,Math.ceil(bonus/2)+(r.duo?rand(1,6):0));target.hp=Math.max(0,target.hp-damage);}target.guard=0;return {r,total,ca,hit,damage};}
  function r27DuelCheckEnd(b){if(!r27DuelAlive(b.ai).length){b.over=true;b.winner='PLAYER';const d=r27DuelEnsure();for(const id of d.aiTeam)if(!d.unlocked.includes(id))d.unlocked.push(id);d.history.push({at:v83ClockLabel(v83EnsureState().clock),result:'VITÓRIA',player:[...d.playerTeam],ai:[...d.aiTeam]});v83SavePoint?.('Duelo 3×3 vencido',[{unlocked:[...d.aiTeam]}]);toast('Vitória 3×3. Oponentes adicionados ao elenco desbloqueado.','success');return true;}if(!r27DuelAlive(b.player).length){b.over=true;b.winner='AI';r27DuelEnsure().history.push({at:v83ClockLabel(v83EnsureState().clock),result:'DERROTA'});v83SavePoint?.('Duelo 3×3 encerrado',[{result:'DERROTA'}]);return true;}return false;}
  function r27DuelAIRound(b){for(const a of r27DuelAlive(b.ai)){if(r27DuelCheckEnd(b))break;const targets=r27DuelAlive(b.player).sort((x,y)=>x.hp-y.hp),t=targets[0];if(!t)break;let kind=a.chakra>=3&&Math.random()<.6?'technique':'attack';if(kind==='technique')a.chakra-=3;if(a.hp/a.maxHp<.3&&Math.random()<.35){a.guard=2;b.log.unshift(`${a.name} assume guarda.`);continue;}const x=r27DuelRoll(a,t,kind);b.log.unshift(`${a.name} ${kind==='technique'?'usa técnica':'ataca'} ${t.name}: ${x.total} vs ${x.ca} • ${x.hit?`${x.damage} dano`:'falha'}.`);}if(!r27DuelCheckEnd(b)){b.round++;b.turn='PLAYER';}saveState(true);render();}
  function r27DuelAction(kind){const d=r27DuelEnsure(),b=d.battle;if(!b||b.over||b.turn!=='PLAYER')return;const a=r27DuelCurrent(b),t=r27DuelTarget(b);if(!a||!t)return;if(kind==='guard'){a.guard=2;b.log.unshift(`${a.name} assume guarda (+2 Defesa até sofrer ataque).`);}else{if(kind==='technique'){if(a.chakra<3)return toast('Chakra insuficiente.','error');a.chakra-=3;}const x=r27DuelRoll(a,t,kind);b.log.unshift(`${a.name} ${kind==='technique'?'usa técnica':'ataca'} ${t.name}: ${x.total} vs ${x.ca} • ${x.hit?`${x.damage} dano`:'falha'}.`);}if(r27DuelCheckEnd(b)){saveState(true);render();return;}b.turn='AI';saveState(true);render();setTimeout(()=>r27DuelAIRound(b),120);}
  function r27RenderDuel(){const d=r27DuelEnsure(),roster=r27DuelRoster(),filter=d.filter||'TODOS';if(d.battle){const b=d.battle;screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">DUELO 3×3 • RODADA ${b.round}</span><h1>${b.over?`Resultado: ${b.winner==='PLAYER'?'Vitória':'Derrota'}`:'Combate de equipes'}</h1><p>Jogador e IA possuem três combatentes com PV/Chakra independentes.</p></div><button class="btn btn-secondary" data-action="r27-duel-reset">Voltar ao álbum</button></div><div class="grid grid-2"><section class="card"><h2>Sua equipe</h2>${b.player.map((x,i)=>`<button class="list-row ${i===b.activeIndex?'active':''}" data-action="r27-duel-active" data-id="${i}" ${x.hp<=0?'disabled':''}><img src="${esc(x.art)}" style="width:60px;height:60px;object-fit:cover"><span><b>${esc(x.name)}</b><small>PV ${x.hp}/${x.maxHp} • Chakra ${x.chakra}/${x.maxChakra} • Defesa ${x.defense}${x.guard?` +${x.guard} guarda`:''}</small></span></button>`).join('')}</section><section class="card"><h2>Equipe IA</h2>${b.ai.map((x,i)=>`<button class="list-row ${i===b.targetIndex?'active':''}" data-action="r27-duel-target" data-id="${i}" ${x.hp<=0?'disabled':''}><img src="${esc(x.art)}" style="width:60px;height:60px;object-fit:cover"><span><b>${esc(x.name)}</b><small>PV ${x.hp}/${x.maxHp} • Chakra ${x.chakra}/${x.maxChakra} • Defesa ${x.defense}</small></span></button>`).join('')}</section></div><section class="card"><h2>Ação</h2><div class="button-row"><button class="btn" data-action="r27-duel-action" data-id="attack" ${b.turn!=='PLAYER'||b.over?'disabled':''}>Atacar</button><button class="btn" data-action="r27-duel-action" data-id="technique" ${b.turn!=='PLAYER'||b.over?'disabled':''}>Técnica • 3 Chakra</button><button class="btn btn-secondary" data-action="r27-duel-action" data-id="guard" ${b.turn!=='PLAYER'||b.over?'disabled':''}>Defender</button></div><h3>Registro</h3>${b.log.slice(0,14).map(x=>`<p class="v82-history-line">${esc(x)}</p>`).join('')}</section>`;return;}
    const shown=roster.filter(n=>filter==='TODOS'||n.r27Era===filter);const selected=new Set(d.playerTeam);screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">SELEÇÃO DE EQUIPE</span><h1>Duelo 3×3</h1><p>Escolha três combatentes. A IA monta um trio diferente; PV, Chakra, defesa e turnos são reais no modo.</p></div></div><section class="card r27-team-top"><h2>Sua equipe (${d.playerTeam.length}/3)</h2><div class="v82-npc-strip">${d.playerTeam.map(id=>{const n=roster.find(x=>x.id===id);return n?`<button data-action="r27-duel-select" data-id="${esc(id)}"><img src="${esc(n.art)}"><span><b>${esc(n.name)}</b><small>Remover</small></span></button>`:''}).join('')||'<p>Use + no álbum.</p>'}</div><div class="button-row"><button class="btn btn-secondary" data-action="r27-duel-ai">Montar equipe IA</button><button class="btn" data-action="r27-duel-start" ${d.playerTeam.length!==3?'disabled':''}>Confirmar time e iniciar</button></div></section><div class="v82-tabs">${['TODOS','ORIGINAL','SHIPPUDEN','REANIMADOS','BORUTO'].map(x=>`<button class="${filter===x?'active':''}" data-action="r27-duel-filter" data-id="${x}">${x}</button>`).join('')}</div><section class="r27-duel-album">${shown.map(n=>`<article class="card ${selected.has(n.id)?'selected':''} ${!r27StoryEnsure().unlockedNpcIds.includes(n.id)?'locked':''}"><img src="${esc(n.art)}" alt="${esc(n.name)}"><h3>${esc(n.name)}</h3><p>${esc(n.role||n.affiliation||'Shinobi')}</p><button class="btn btn-small" data-action="r27-duel-select" data-id="${esc(n.id)}" ${!r27StoryEnsure().unlockedNpcIds.includes(n.id)?'disabled':''}>${selected.has(n.id)?'✓ Selecionado':r27StoryEnsure().unlockedNpcIds.includes(n.id)?'＋':'🔒 História'}</button></article>`).join('')}</section>`;}
  const renderR27DuelBase=render;
  render=function(){if(ui.screen==='duelo-r27'){renderChrome();r27RenderDuel();return;}return renderR27DuelBase();};
