  renderTacticalBoard=function(b){const reachable=[];for(let y=0;y<12;y++)for(let x=0;x<12;x++)if(!b.moveUsed&&gridDistance(b.playerPos,{x,y})<=3)reachable.push(`${x},${y}`);const pos=b.enemyPositions||{};return `<div class="tactical-board">${b.terrain.map(c=>{const key=`${c.x},${c.y}`,player=b.playerPos.x===c.x&&b.playerPos.y===c.y,enemy=r27ActiveEnemies(b).find(e=>pos[e.id]?.x===c.x&&pos[e.id]?.y===c.y)||(b.enemyPos.x===c.x&&b.enemyPos.y===c.y?b.enemy:null);return `<button class="tactical-cell ${esc(c.type)} ${reachable.includes(key)&&!enemy?'reachable':''}" data-action="tactical-move" data-x="${c.x}" data-y="${c.y}" ${player||enemy||b.moveUsed?'disabled':''}>${player?`<span class="tactical-unit player">🥷</span>`:''}${enemy?`<span class="tactical-unit enemy" title="${esc(enemy.name)}">👺</span>`:''}</button>`;}).join('')}</div>`;};
