  function r29Family(o={}){const t=v75Norm(`${o.id||''} ${o.name||o.nome||''} ${o.description||o.descricao||''} ${o.element||o.elemento||''} ${o.category||o.categoria||''}`);if(/katon|fogo|fire|chama|amaterasu/.test(t))return 'fire';if(/raiton|raio|relamp|lightning|eletric/.test(t))return 'lightning';if(/suiton|agua|water|nevoa|gelo/.test(t))return 'water';if(/fuuton|futon|vento|wind/.test(t))return 'wind';if(/doton|mokuton|terra|earth|madeira|areia/.test(t))return 'earth';if(/kugangan|dojutsu|sharingan|byakugan|rinne|espac|portal|vazio|kūsenr|kusenr|kurai|genjutsu/.test(t))return 'space';return 'mixed';}
