  const v81CapArtR29Base=v81CapArt;v81CapArt=function(cap,i=0){if(/kurai|suirin|kūsenr|kusenr|kugangan/i.test(`${cap?.name||''} ${cap?.categoria||''}`))return v81CapArtR29Base(cap,i);return r29AssetFor(cap)||v81CapArtR29Base(cap,i);};

