  function r29ActiveCanonEvent(){if(!state.character)return null;const career=r29Ensure().career;if(!v81IsLeon()&&career.rank==='Estudante')return null;const c=r27CanonEnsure(),arc=c.activeArcId;return R27_CANON_EVENTS.find(e=>e.arcId===arc&&c.status[e.id]!=='RESOLVED'&&c.status[e.id]!=='RESOLVED_HISTORICAL')||R27_CANON_EVENTS.find(e=>e.arcId===arc)||null;}
