  const renderAptitudesR29Base=renderAptitudes;renderAptitudes=function(){const c=state.character;if(!c)return renderAptitudesR29Base();const list=LIV.aptidoes||[];screen.innerHTML=`<div class="v82-page-head"><div><span class="eyebrow">APTIDÕES • ASSETS DO ACERVO DO USUÁRIO</span><h1>Aptidões</h1><p>As artes abaixo vêm das pranchas enviadas no RAR e são escolhidas de forma determinística por aptidão/categoria, no lugar do ícone repetido.</p></div></div><div class="catalog-grid">${list.map(a=>{const have=state.aptitudes.includes(a.id),art=r29AssetFor(a);return `<article class="card catalog-card"><img class="r29-card-art" src="${esc(art)}" alt=""><span class="eyebrow">${esc(a.categoria||'Aptidão')}</span><h3>${esc(a.nome)}</h3><p>${esc(a.resumo||'')}</p><small>${esc(a.req||'Sem requisito adicional')}</small><button class="btn" data-action="buy-aptitude" data-id="${esc(a.id)}" ${have||Number(c.aptitudePoints||0)<Number(a.custo||1)?'disabled':''}>${have?'Adquirida':`Adquirir • ${a.custo||1} PA`}</button></article>`}).join('')}</div>`;};

  // Leon usa o mesmo tabuleiro 12×12 do motor global, com imagem real nos tokens.
  r27BattleDims=function(){return {w:12,h:12};};
