  const v8StartLeonBattleR29Base=v8StartLeonBattle;v8StartLeonBattle=function(elite=false){const out=v8StartLeonBattleR29Base(elite);const b=ui.battle;if(b&&state.character?.privateCharacter==='leon'){b.terrain=v8LeonTerrain();b.playerPos={x:1,y:10};b.enemyPos={x:9,y:2};if(b.enemies?.length){b.enemyPositions=b.enemyPositions||{};b.enemies.forEach((e,i)=>b.enemyPositions[e.id]={x:8+(i%3),y:1+Math.floor(i/3)*2});r27SyncBattleTarget(b);}saveState(true);render();}return out;};
  v8LeonBoard=function(b){const reachable=[];for(let y=0;y<12;y++)for(let x=0;x<12;x++)if(!b.moveUsed&&gridDistance(b.playerPos,{x,y})<=3)reachable.push(`${x},${y}`);const pos=b.enemyPositions||{},playerArt=state.character?.avatar||r31Asset('characters','leon kosmo')||'assets/r31/entities/characters/0076-leon-kosmo.webp';return `<div class="tactical-board v8-leon-board r29-board">${b.terrain.map(c=>{const key=`${c.x},${c.y}`,player=b.playerPos.x===c.x&&b.playerPos.y===c.y,enemy=r27ActiveEnemies(b).find(e=>pos[e.id]?.x===c.x&&pos[e.id]?.y===c.y)||(b.enemyPos?.x===c.x&&b.enemyPos?.y===c.y?b.enemy:null),art=enemy?.art||r29AssetFor(enemy||{},'mixed');return `<button class="tactical-cell ${esc(c.type)} ${reachable.includes(key)&&!enemy?'reachable':''}" data-action="v8-leon-move" data-x="${c.x}" data-y="${c.y}" ${player||enemy||b.moveUsed||b.over?'disabled':''}>${player?`<span class="r29-unit player"><img src="${esc(playerArt)}"><small>Leon</small></span>`:''}${enemy?`<span class="r29-unit enemy" title="${esc(enemy.name)}"><img src="${esc(art)}"><small>${esc(enemy.name)}</small></span>`:''}</button>`;}).join('')}</div>`;};

