  window.__NARUTO_R29__.testStudentDirector=()=>{const prevState=state,prevBattle=ui.battle,prevMission=ui.currentMission;try{state=defaultState();state.character={name:'QA Estudante',graduation:'Estudante',level:1,xp:0,ryo:100,hp:20,maxHp:20,chakra:12,maxChakra:12,stamina:10,maxStamina:10,village:'folha',skills:{},conditions:[],privateCharacter:''};const r=r29Ensure(),d=r29DirectorTick('qa_student');const assigned=Object.values(d.assignments).filter(a=>['ASSIGNED','ACTIVE'].includes(a.status));return {rank:r.career.rank,main:assigned.filter(a=>a.kind==='main').map(a=>a.missionId),extra:assigned.filter(a=>a.kind!=='main').map(a=>a.missionId),activeCanon:r29ActiveCanonEvent()?.id||'',promotion:r29PromotionRequirements('Estudante')};}finally{state=prevState;ui.battle=prevBattle;ui.currentMission=prevMission;}};
  window.__NARUTO_R29__.testStudentPromotion=async()=>{const prevState=state,prevBattle=ui.battle,prevMission=ui.currentMission,prevStatus=r27Copy(ui.aiStatus);try{state=defaultState();state.character={name:'QA Estudante',graduation:'Estudante',graduationId:0,level:1,xp:0,ryo:100,hp:20,maxHp:20,chakra:12,maxChakra:12,stamina:10,maxStamina:10,village:'folha',skills:{},conditions:[],privateCharacter:''};ui.aiStatus={...ui.aiStatus,enabled:false};const r=r29Ensure();r.career.counts.TASK=3;r29UpdatePromotionPending();const review=await r29RankReview();return {rank:r.career.rank,graduation:state.character.graduation,history:r27Copy(r.career.history),review};}finally{state=prevState;ui.battle=prevBattle;ui.currentMission=prevMission;ui.aiStatus=prevStatus;}};
