  function r30Ensure(){const r=r29Ensure();state.r30=state.r30||{};state.r30.version=R30_VERSION;state.r30.titles=state.r30.titles||{unlocked:[],active:'',history:[]};state.r30.secrets=state.r30.secrets||{};for(const s of R30_SECRET_EVENTS)state.r30.secrets[s.id]=state.r30.secrets[s.id]||{id:s.id,status:'HIDDEN',discoveredAt:'',resolvedAt:'',source:''};return state.r30;}
