  // =========================================================
  // R32 — CONTINUIDADE DE MISSÃO, PERSISTÊNCIA E NARRADOR
  // =========================================================
  const R32_VERSION='R32-MISSION-CONTINUITY-2026-08-13';
  function r32Clone(v){try{return JSON.parse(JSON.stringify(v));}catch{return v;}}
  function r32MissionRuntime(){
    state.missionRuntime=(state.missionRuntime&&typeof state.missionRuntime==='object')?state.missionRuntime:{};
    state.missionRuntime.version=R32_VERSION;
    state.missionRuntime.active=state.missionRuntime.active||null;
    state.missionRuntime.log=Array.isArray(state.missionRuntime.log)?state.missionRuntime.log:[];
    state.missionRuntime.history=Array.isArray(state.missionRuntime.history)?state.missionRuntime.history:[];
    return state.missionRuntime;
  }
  function r32ActiveAssignment(){
    const d=r29Ensure().director,arr=Object.values(d.assignments||{}).filter(a=>a?.status==='ACTIVE'&&missionById(a.missionId));
    if(!arr.length)return null;
    arr.sort((a,b)=>Number(b.startedAtMs||0)-Number(a.startedAtMs||0)||String(b.assignedAt||'').localeCompare(String(a.assignedAt||'')));
    const chosen=arr[0];
    for(const other of arr.slice(1)){
      other.status='ASSIGNED';
      other.dependsOnMissionId=other.dependsOnMissionId||chosen.missionId;
      other.dependencyReason=other.dependencyReason||'Aguarda a missão que já estava em andamento.';
    }
    return chosen;
  }
  function r32PersistMissionRuntime(){
    const rt=r32MissionRuntime();
    rt.active=ui.currentMission?r32Clone(ui.currentMission):null;
    rt.log=Array.isArray(ui.missionLog)?r32Clone(ui.missionLog):[];
    rt.screen=ui.currentMission?'missao-ativa':'';
    rt.updatedAt=Date.now();
    if(ui.currentMission){
      const a=r29Assignment(ui.currentMission.id);
      if(a){a.status='ACTIVE';a.startedAtMs=a.startedAtMs||Number(ui.currentMission.startedAt||Date.now());}
    }
    return rt;
  }
  function r32RestoreMissionRuntime(){
    const rt=r32MissionRuntime();
    if(rt.active?.id&&state.completedMissions.includes(rt.active.id)){rt.history.push({id:rt.active.id,status:'DONE',at:Date.now()});rt.active=null;rt.log=[];}
    if(!ui.currentMission&&rt.active?.id&&missionById(rt.active.id)&&!state.completedMissions.includes(rt.active.id)){
      ui.currentMission=r32Clone(rt.active);
      ui.currentMission.aiNarratives=Array.isArray(ui.currentMission.aiNarratives)?ui.currentMission.aiNarratives:[];
      ui.missionLog=Array.isArray(rt.log)&&rt.log.length?r32Clone(rt.log):[{text:`Missão restaurada: ${missionById(rt.active.id)?.name||rt.active.id}`,type:'info'}];
      const a=r29Assignment(rt.active.id);if(a)a.status='ACTIVE';
      return ui.currentMission;
    }
    if(!ui.currentMission){
      const a=r32ActiveAssignment();
      if(a&&!state.completedMissions.includes(a.missionId)){
        const m=missionById(a.missionId);
        ui.currentMission={id:m.id,stage:0,successes:0,failures:0,startedAt:Number(a.startedAtMs||Date.now()),narrative:m.description,aiNarratives:[],restoredFromAssignment:true};
        ui.missionLog=[{text:`Missão ativa recuperada do save: ${m.name}. O progresso de etapa anterior à R32 não podia ser reconstruído com segurança e não foi inventado.`,type:'info'}];
        r32PersistMissionRuntime();
        return ui.currentMission;
      }
    }
    return ui.currentMission;
  }
  function r32ActiveMission(){return r32RestoreMissionRuntime();}
  function r32MissionDependencyIds(m){
    if(!m)return [];
    const a=r29Assignment(m.id)||{},raw=[m.requiresMission,m.requiresMissionId,m.previousMissionId,m.dependsOnMissionId,a.dependsOnMissionId];
    for(const v of [m.requiresMissions,m.prerequisiteMissions,m.prerequisites?.missions])if(Array.isArray(v))raw.push(...v);
    return [...new Set(raw.flatMap(x=>Array.isArray(x)?x:[x]).filter(Boolean).map(String))].filter(id=>id!==m.id);
  }
  function r32MissionContinuityGate(m){
    if(!m)return {ok:false,reason:'Missão inexistente.'};
    const run=r32ActiveMission();
    if(run&&run.id!==m.id){
      const active=missionById(run.id);
      return {ok:false,reason:`Continuidade: conclua ou abandone “${active?.name||run.id}” antes de iniciar outra missão.`,blockedBy:run.id};
    }
    const missing=r32MissionDependencyIds(m).filter(id=>!state.completedMissions.includes(id));
    if(missing.length){
      const names=missing.map(id=>missionById(id)?.name||id);
      return {ok:false,reason:`Continuidade da história: conclua primeiro ${names.map(x=>`“${x}”`).join(', ')}.`,blockedBy:missing};
    }
    const a=r29Assignment(m.id);
    if(a?.kind==='main'){
      const earlier=Object.values(r29Ensure().director.assignments||{}).filter(x=>x&&x.kind==='main'&&x.missionId!==m.id&&!['DONE','FAILED','ABANDONED','LOCKED_ARC'].includes(x.status)&&missionById(x.missionId));
      if(earlier.length){const x=earlier[0],pm=missionById(x.missionId);return {ok:false,reason:`História encadeada: “${pm?.name||x.missionId}” precisa ser resolvida antes desta missão principal.`,blockedBy:x.missionId};}
    }
    return {ok:true,reason:''};
  }

  // Salvar missão é parte do SAVE do personagem, nunca estado transitório de UI.
  const saveStateR32Base=saveState;
  saveState=function(silent=false){r32PersistMissionRuntime();return saveStateR32Base(silent);};

  // Qualquer nova designação feita enquanto existe missão ativa fica em espera.
  const r29AssignMissionR32Base=r29AssignMission;
  r29AssignMission=function(m,kind,reason){
    const before=r29Assignment(m?.id),rec=r29AssignMissionR32Base(m,kind,reason),run=ui.currentMission||r32MissionRuntime().active;
    if(rec&&run?.id&&run.id!==m?.id&&!state.completedMissions.includes(run.id)){
      rec.dependsOnMissionId=rec.dependsOnMissionId||run.id;
      rec.dependencyReason=rec.dependencyReason||`Aguarda conclusão de ${missionById(run.id)?.name||run.id}.`;
      if(rec.status==='ACTIVE')rec.status='ASSIGNED';
    }
    return rec||before;
  };

  // O acesso final agora respeita a missão que já está rodando e dependências explícitas.
  const r29MissionAccessR32Base=r29MissionAccess;
