    const run=r32ActiveMission();
    if(run){
      if(run.id===id){ui.screen='missao-ativa';const a=r29Assignment(id);if(a)a.status='ACTIVE';r32PersistMissionRuntime();saveStateR32Base(true);render();return {ok:true,resumed:true,id};}
      const active=missionById(run.id);toast(`A missão “${active?.name||run.id}” já está em andamento. Termine ou abandone-a antes de aceitar outra.`,'error',7000);return {ok:false,blockedBy:run.id};
    }
    const access=r29MissionAccess(missionById(id));if(!access.ok){toast(access.reason,'error',7000);return {ok:false,reason:access.reason};}
    const out=startMissionR32Base(id);
