  // =========================================================
  // R35 — HARDENING DOS FLUXOS QUE O USUÁRIO EXIGIU
  // Intercepta decisão de missão uma única vez, torna erro visível,
  // reforça nível inicial TERION e expõe estado real de acesso online.
  // =========================================================
  const R35_VERSION='R35-REQUEST-HARDENING-2026-08-13';

  // Personagem comum sempre nasce no início da carreira. Leon mantém seu estado privado.
  const createCharacterR35Base=createCharacter;
  createCharacter=function(){
    const before=state.character;
    const out=createCharacterR35Base();
    const c=state.character;
    if(c&&c!==before&&!c.privateCharacter){
      c.level=1;c.nc=1;c.graduation='Estudante';c.graduationId='estudante';
      c.xp=0;c.totalXp=0;c.xpTotalConfirmado=0;
      c.rulesContract={...(c.rulesContract||{}),engine:'TERION 2D10',initialLevel:1,initialNC:1,initialGraduation:'Estudante'};
      recalc(c,true);saveState(true);
    }
    return out;
  };

  function r35MissionError(err){
    const msg=String(err?.stack||err?.message||err||'Erro desconhecido');
    r34RecordClientError?.('mission',msg,'mission-choice',0,0);
    const box=document.createElement('section');box.className='notice danger r35-mission-error';
    box.innerHTML=`<b>ERRO REAL DA MISSÃO</b><br>${esc(msg.slice(0,1200))}<br><small>O erro foi salvo em Diagnóstico local; a missão não foi marcada como concluída.</small>`;
    const host=screen.querySelector('.section-title,.v82-page-head')||screen;host.insertAdjacentElement('afterend',box);
    toast('A escolha da missão falhou e NÃO foi aplicada. Veja o erro na tela.','error',7000);
  }

  // Captura antes do dispatcher legado para impedir clique duplo/duas resoluções da mesma escolha.
  document.addEventListener('click',async e=>{
    const btn=e.target?.closest?.('[data-action="mission-choice"]');
    if(!btn)return;
    e.preventDefault();e.stopImmediatePropagation();
    if(btn.disabled)return;
    btn.disabled=true;
    try{await resolveMissionChoice(Number(btn.dataset.id));}
    catch(err){btn.disabled=false;r35MissionError(err);}
  },true);

  // O status online deixa de ser implícito: a tela mostra exatamente local / Worker / salas.
  const renderConfigR35Base=renderConfig;
  renderConfig=function(){
    renderConfigR35Base();
    const s=ui.aiStatus||{},card=document.createElement('section');card.className='card r35-online-status';
    card.innerHTML=`<span class="eyebrow">ACESSO PELA INTERNET • R34/R35</span><h3>Estado real da conectividade</h3><div class="list"><div class="list-row"><span>Servidor local</span><b>${s.localServer?'ATIVO':'NÃO CONFIRMADO'}</b></div><div class="list-row"><span>Cloud save / Worker</span><b>${s.cloudSave?'ATIVO':'NÃO CONFIGURADO'}</b></div><div class="list-row"><span>Salas online</span><b>${s.onlineRooms?'ATIVAS':'NÃO CONFIRMADAS'}</b></div></div><p class="muted">O jogo não chama localhost de “online mundial”. A URL pública só é considerada ativa quando o Worker/Tunnel responder.</p>`;
    screen.prepend(card);
  };

  // Imagem quebrada não fica vazia: registra o caminho e aplica fallback seguro de interface.
