  const R382_VERSION='R40-TAXONOMIA-NARRATIVA-SEMANTICA-2026-08-15';
  const R382_SCRIPTS=R33Q.scripts||{};
  function r382ContentType(x){const s=typeof x==='string'?R382_SCRIPTS[x]:R382_SCRIPTS[x?.id];if(s?.contentType)return s.contentType;if(x?.type==='CANON')return 'CANON_EVENT';if(x?.rank==='TASK'||String(x?.id||'').startsWith('task'))return 'TASK';if(x?.r30Secret)return 'SECRET_TRIAL';return 'MISSION';}
  function r382TrueMissions(){return (CAT.missions||[]).filter(m=>r382ContentType(m)==='MISSION');}
  function r382Tasks(){return (CAT.missions||[]).filter(m=>r382ContentType(m)==='TASK');}
  function r382Events(){return R27_CANON_EVENTS||[];}
  function r382Script(id){return R382_SCRIPTS[String(id)]||null;}
  function r382Mode(id){return r382Script(id)?.narrativeMode||'STRUCTURED';}
  function r382ModeLabel(mode){return {STRUCTURED:'Estruturada',HYBRID_AI:'Híbrida + IA',NARRATIVE_AI:'Narrativa com IA',WORLD_EVENT_AI:'Evento narrado por IA'}[mode]||mode;}
  function r382CampaignForArc(arcId){return (WORLD84.campaigns||[]).find(c=>(c.arcIds||c.arcs||[]).includes(arcId))||null;}
