    if(Number(d.interludeRemaining||0)<=0&&arc&&!active.some(a=>a.kind==='main')){const hit=r382ArcMissionCandidate(arc);if(hit){hit.m.r382ArcMission=true;hit.m.r382ArcId=arc.id;const rec=r29AssignMission(hit.m,'main',`Missão formal relacionada ao arco ${arc.id}; o evento canônico continua sendo evento e será resolvido por cenas/estado do mundo.`);rec.arcId=arc.id;rec.canonEventId=ev?.id||'';rec.relevanceScore=hit.score;}}
    const now=Object.values(d.assignments).filter(a=>['ASSIGNED','ACTIVE'].includes(a.status));const needSide=Math.max(Number(d.interludeRemaining||0),now.some(a=>a.kind==='main')?1:2);let have=now.filter(a=>a.kind!=='main').length;
