    const card=({a,m})=>{const script=r382Script(m.id),access=r29MissionAccess(m),mode=script?.narrativeMode||'STRUCTURED',label=r382ContentType(m)==='TASK'?'TAREFA DA ACADEMIA':a?.kind==='main'?'MISSÃO DO ARCO':a?.kind==='filler'?'MISSÃO DE GRADUAÇÃO':'MISSÃO DE CAMPO';return `<article class="card r29-mission-card ${a?.kind||'locked'}"><img src="${esc(r29AssetFor(m,'earth'))}" alt=""><div><span class="eyebrow">${label} • Rank ${esc(m.rank)}</span><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="tags"><span class="badge">${esc(r382ModeLabel(mode))}</span><span class="badge">TERION 2D10</span>${a?.arcId?`<span class="badge">${esc(a.arcId)}</span>`:''}</div>${a?`<small>${esc(a.reason||'Designada pelo Diretor.')}</small><button class="btn" data-action="start-mission" data-id="${esc(m.id)}" ${access.ok?'':`disabled title="${esc(access.reason)}"`}>${a.status==='ACTIVE'?'Continuar':r382ContentType(m)==='TASK'?'Iniciar tarefa':'Aceitar missão'}</button>`:`<p class="r29-lock">🔒 Não designada pelo Diretor/Mestre IA.</p>`}</div></article>`};
