  async function r382NarrateArc(){const ns=r382NarrativeState(),canon=r27CanonEnsure(),arc=r382ArcById(ns.selectedArcId||canon.activeArcId),camp=arc?r382CampaignForArc(arc.id):null;if(!arc)return toast('Nenhum arco selecionado.','error');if(/CONCLUIDO|CONCLUÍDO|HISTORICO|HISTÓRICO/i.test(String(arc.status||''))){const next=(WORLD84.arcs||[]).find(a=>/DISPONIVEL|ATIVO|EM_ANDAMENTO/i.test(String(a.status||'')));if(next){ns.selectedArcId=next.id;const nc=r382CampaignForArc(next.id);if(nc)ns.selectedCampaignId=nc.id;saveState(true);toast(`O arco ${arc.name} já está encerrado. Próximo arco jogável selecionado: ${next.name}.`,'info',6500);render();return;}return toast('Este arco já está concluído e permanece apenas como histórico.','info',5500);}const done=b=>/DONE|RESOLVED|CONCLUIDO|CONCLUÍDO|SUPERADO|HISTORICO|HISTÓRICO/i.test(String(b?.status||''));const pending=(arc.mandatoryBeats||[]).find(b=>!done(b))||(arc.optionalBeats||[]).find(b=>!done(b));ui.aiPending=true;render();try{const result=await callAI({mode:'arc_scene',prompt:`CAMPANHA: ${camp?.name||'sem campanha'}. ARCO: ${arc.name}. Premissa: ${arc.premise}. Beat pendente: ${pending?.label||'continuidade orgânica do arco'}. Gere UMA CENA de RPG coerente com local, tempo, NPCs presentes e estado vivo. Isto é CENA/ARCO, não missão. Não crie recompensa, rank ou objetivo formal de missão a menos que o Diretor tenha designado uma missão separada. Não aplique PV/Chakra/itens por prosa; TERION 2D10 é autoridade mecânica.`,state:aiGameContext(),history:ui.aiChat.slice(-10)});const scene={id:'scene-r382-'+Date.now(),campaignId:camp?.id||'',arcId:arc.id,eventId:r29ActiveCanonEvent()?.id||'',title:result?.scene?.title||arc.name,narrative:result?.scene?.narrative||result?.narrativa||'',at:v83ClockLabel(v83EnsureState().clock),contentType:'SCENE'};ns.scenes.push(scene);ns.scenes=ns.scenes.slice(-80);ns.selectedArcId=arc.id;ns.selectedCampaignId=camp?.id||'';saveState(true);}catch(err){toast(`Falha ao narrar arco: ${err.message||err}`,'error');}finally{ui.aiPending=false;ui.screen='narrativa-r382';render();}}

