  renderActiveMission=function(){renderActiveMissionR382Base();const run=ui.currentMission,m=run&&missionById(run.id),script=m&&r382Script(m.id);if(!run||!m||!script)return;const host=screen.querySelector('.r33-mission-mechanics')||screen.querySelector('.section-title,.v82-page-head');host?.insertAdjacentHTML('afterend',`<section class="notice"><b>${r382ContentType(m)==='TASK'?'TAREFA':'MISSÃO'} • ${esc(r382ModeLabel(script.narrativeMode))}</b><br>${esc(script.missionIdentity?.primaryObjective||script.objective||m.description)}<br><small>${r382ContentType(m)==='TASK'?'Tarefa não entra na contagem das 437 missões.':'Campanha/arco/evento não são esta missão; aqui existe objetivo formal e resolução própria.'}</small></section>`);if(['HYBRID_AI','NARRATIVE_AI'].includes(script.narrativeMode)){const target=screen.querySelector('.choice-grid.r33-choice-grid')?.parentElement||screen.querySelector('.card');target?.insertAdjacentHTML('beforeend',`<div class="card r382-free-action"><h3>Ação livre nesta cena</h3><p class="muted">A IA narra a consequência contextual. Nenhum número muda até uma resolução TERION válida.</p><textarea id="r382-mission-free-action" class="input" rows="3" placeholder="Diga exatamente o que seu personagem tenta fazer..."></textarea><button class="btn btn-info" data-action="r382-mission-free-action" ${ui.aiPending?'disabled':''}>Enviar ao Mestre IA</button></div>`);}
  };
  async function r382MissionFreeAction(){const run=ui.currentMission,m=run&&missionById(run.id),script=m&&r382Script(m.id),stage=script?.stages?.[Number(run?.stage||0)],el=document.getElementById('r382-mission-free-action'),action=String(el?.value||'').trim();if(!run||!m||!script||!stage||!action)return toast('Escreva a ação antes de enviar.','error');ui.aiPending=true;render();try{const result=await callAI({mode:'mission_narrative_action',prompt:`MISSÃO FORMAL: ${m.name}. Objetivo: ${script.missionIdentity?.primaryObjective||m.description}. Modo: ${script.narrativeMode}. Cena atual: ${stage.title} — ${stage.scene}. Ação livre do jogador: ${action}. Narre a reação imediata e indique qual risco/teste faria sentido, mas NÃO resolva mecanicamente e NÃO altere recursos por texto. As opções TERION do motor continuam sendo a autoridade para testes e custos.`,actions:stage.choices.map(c=>({id:c.id,label:c.label,test:c.skill,risk:c.risk})),state:aiGameContext(),history:ui.aiChat.slice(-8)});const text=String(result?.scene?.narrative||result?.narrativa||'').trim();if(text){run.aiNarratives=Array.isArray(run.aiNarratives)?run.aiNarratives:[];run.aiNarratives.push(text);run.narrative=text;r382NarrativeState().missionFreeActions.push({missionId:m.id,stage:Number(run.stage||0),action,narrative:text,at:Date.now()});r382NarrativeState().missionFreeActions=r382NarrativeState().missionFreeActions.slice(-100);}r32PersistMissionRuntime?.();saveState(true);}catch(err){toast(`Falha na ação narrativa: ${err.message||err}`,'error');}finally{ui.aiPending=false;ui.screen='missao-ativa';render();}}

  // Auto-narração inicial somente para modos que declaradamente usam IA.
