  // ---------- QUESTS DE MAPA: gameplay antes do teste ----------
  eventTestV74=async function(e){const c=state.character;if(!c)return;const p=Number(state.events.progress[e.id]||0),stages=Number(e.stages||2);if(c.privateCharacter!=='leon'&&c.stamina<Number(e.stamina||0))return toast('Vigor insuficiente para continuar este evento.','error');const type=r41GameForText(`${e.tipo} ${e.nome} ${e.skill}`),mg=await r41OpenMinigame(type,{source:'map_event',eventId:e.id,stage:p}),bridge=window.SNSMinigameEngine?.terionModifier?.(mg)||{modifier:mg.success?1:0};let ok=false,label='';
    if(c.privateCharacter==='leon'){const skill=Number(c.specialProfile?.skillRatings?.[e.skill]??c.specialProfile?.skillRatings?.['Controle Espacial']??1),dice=rollLeon2d10(),total=dice.hope+dice.doom+skill+Number(bridge.modifier||0);ok=total>=Number(e.cd||11);label=`${dice.hope} + ${dice.doom} + ${skill}${bridge.modifier?` + ${bridge.modifier} minijogo`:''} = ${total} vs CD ${e.cd}`;}
    else{c.stamina=Math.max(0,c.stamina-Number(e.stamina||0));r41CircumstantialBonus=Number(bridge.modifier||0);const bonus=skillTotal(e.skill)||Number(c.attributes?.percepcao||0),d=rollTerion2d10(),total=d.total+bonus;r41CircumstantialBonus=0;ok=total>=Number(e.cd||11);label=`${d.rolls.join(' + ')} + ${bonus} = ${total} vs ${e.cd}`;}
    const next=ok?p+1:p;state.events.progress[e.id]=next;state.world.events.push(`${e.nome} • minijogo ${mg.score}/1000 • ${label} — ${ok?'sucesso':'falha'}.`);v83Commit?.('map_event_gameplay',{label:e.nome,eventId:e.id,minigame:type,score:mg.score,success:ok},Math.max(10,Math.round(mg.time||20)));v83SavePoint?.(`Evento ${e.nome}`,[{stage:p,score:mg.score,success:ok}]);saveState(true);if(ok&&next>=stages)completeEventV74(e);else{toast(ok?`Etapa concluída (${next}/${stages}).`:`Falha no teste após o minijogo. O mundo e o tempo permanecem avançados.`,ok?'success':'info',5000);render();}
  };
