  // ---------- MUNDO VISUAL / AMBIENTE ----------
  const R41_ACTIVITIES={coleta:{label:'Coleta',game:'tracking',minutes:40},craft:{label:'Criação / Craft',game:'fuinjutsu',minutes:60},pesca:{label:'Pesca',game:'water_walk',minutes:60},caca:{label:'Caça',game:'tracking',minutes:90},entrega:{label:'Entrega',game:'pursuit',minutes:45},colecionavel:{label:'Procurar colecionável',game:'investigation',minutes:50}};
  async function r41DoActivity(id){const def=R41_ACTIVITIES[id],c=state.character;if(!def||!c)return;const r=r41Ensure();r.activities=r.activities||{materials:0,collectibles:[],history:[]};if(id==='craft'&&Number(r.activities.materials||0)<2)return toast('Craft exige 2 materiais obtidos em coleta/caça.','error');const mg=await r41OpenMinigame(def.game,{source:'world_activity',activity:id}),bridge=window.SNSMinigameEngine?.terionModifier?.(mg)||{modifier:0},dice=c.privateCharacter==='leon'?rollLeon2d10():rollTerion2d10(),base=c.privateCharacter==='leon'?Number(c.specialProfile?.skillRatings?.Sobrevivencia||c.specialProfile?.skillRatings?.Investigacao||3):Number(skillTotal(id==='craft'?'criacao':'sobrevivencia')||c.attributes?.percepcao||2),total=(dice.total??(dice.hope+dice.doom))+base+Number(bridge.modifier||0),cd=id==='craft'?12:id==='caca'?13:11,ok=total>=cd;let reward='';if(ok){if(id==='coleta'){r.activities.materials+=1+Math.floor(mg.score/500);reward=`+${1+Math.floor(mg.score/500)} material(is)`;}else if(id==='caca'){r.activities.materials+=2;state.inventory.racao_viagem=Number(state.inventory.racao_viagem||0)+1;reward='+2 materiais + 1 ração';}else if(id==='pesca'){state.inventory.racao_viagem=Number(state.inventory.racao_viagem||0)+1;reward='+1 ração de viagem';}else if(id==='entrega'){c.ryo=Number(c.ryo||0)+10;state.story.reputation=Number(state.story.reputation||0)+1;reward='+10 Ryos +1 reputação';}else if(id==='craft'){r.activities.materials-=2;state.inventory.bomba_fumaca=Number(state.inventory.bomba_fumaca||0)+1;reward='2 materiais → 1 bomba de fumaça';}else{const cid=`colecao_${Date.now().toString(36)}`;r.activities.collectibles.push(cid);reward='colecionável registrado';}}else reward='sem recompensa; tempo foi gasto';r.activities.history.push({at:Date.now(),clock:r41AbsMinute(),id,score:mg.score,total,cd,ok,reward});r.activities.history=r.activities.history.slice(-80);v83Commit?.('world_activity',{label:def.label,activity:id,score:mg.score,total,cd,success:ok,reward},def.minutes);v83SavePoint?.(`Atividade: ${def.label}`,[{activity:id,success:ok,reward}]);r41BroadcastGameplay('world_activity',{activity:id,success:ok,reward,score:mg.score});saveState(true);render();toast(`${def.label}: ${ok?'sucesso':'falha'} • ${reward}.`,ok?'success':'info',5500);}
  const renderVillageR41Base=renderVillage;
  renderVillage=function(){renderVillageR41Base();const map=screen.querySelector('.play-map,.world-map');if(map&&!map.querySelector('.r41-ambient-layer')){const clock=v83EnsureState?.()?.clock||{},hour=Number(clock.hour||12),weather=state.masterV84?.world?.weather||state.r41?.world?.weather||'clear';map.insertAdjacentHTML('beforeend',`<div class="r41-ambient-layer ${esc(weather)} ${hour<6||hour>=19?'night':'day'}" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>`);}if(ui.mapMode!=='world'&&!screen.querySelector('.r41-activities')){const a=r41Ensure().activities||{materials:0,collectibles:[]};screen.insertAdjacentHTML('beforeend',`<section class="card r41-activities" style="margin-top:14px"><span class="eyebrow">ATIVIDADES SECUNDÁRIAS • GAMEPLAY</span><h2>Viver na vila também gasta tempo</h2><p>Coleta, craft, pesca, caça e entregas abrem minijogo, passam por TERION, avançam o mundo e salvam. Materiais: <b>${Number(a.materials||0)}</b> • Colecionáveis: <b>${(a.collectibles||[]).length}</b>.</p><div class="button-row">${Object.entries(R41_ACTIVITIES).map(([id,x])=>`<button class="btn btn-secondary" data-action="r41-activity" data-id="${id}">${x.label}</button>`).join('')}</div></section>`);}};
  document.addEventListener('click',e=>{const b=e.target?.closest?.('[data-action="r41-activity"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();r41DoActivity(b.dataset.id);},true);

  // ---------- ONLINE: ações sincronizadas de equipe além de chat ----------
  async function r41OnlineAction(action,payload={}){const o=ensureOnlineState();if(!o.roomId)throw new Error('Entre em uma sala.');const d=await onlinePost('/api/online/action',{roomId:o.roomId,playerId:state.playerId,characterName:state.character?.name||'Shinobi',action,payload,character:onlineCharacterSummary()});return d;}
  async function r41OnlineRefresh(){const o=ensureOnlineState();if(!o.roomId)return;try{const d=await onlinePost('/api/online/state',{roomId:o.roomId,afterId:Number(r41Ensure().online.actionCursor||0)}),fresh=Array.isArray(d.actions)?d.actions:[];const rr=r41Ensure().online;rr.actions=[...(rr.actions||[]),...fresh].slice(-120);rr.actionCursor=rr.actions.reduce((m,x)=>Math.max(m,Number(x.id)||0),Number(rr.actionCursor||0));rr.shared=d.shared||rr.shared||{};}catch(e){console.warn('R41 online state',e.message);}}
  async function r41SendOnlineIntent(){const input=document.getElementById('r41-online-intent'),text=String(input?.value||'').trim();if(!text)return toast('Descreva a ação da equipe.','error');try{await r41OnlineAction('intent',{text,scene:ui.currentMission?.id||WORLD84.currentScene?.id||'',screen:ui.screen});if(input)input.value='';await r41OnlineRefresh();render();toast('Ação enviada para a equipe.','success');}catch(e){toast(e.message,'error',5500);}}
  const refreshOnlineRoomR41Base=refreshOnlineRoom;
  refreshOnlineRoom=async function(silent=false){const out=await refreshOnlineRoomR41Base(silent);await r41OnlineRefresh();if(ui.screen==='online')render();return out;};
  const renderOnlineR41Base=renderOnline;
  renderOnline=function(){renderOnlineR41Base();const o=ensureOnlineState();screen.querySelectorAll('p').forEach(p=>{if(/Combate simultâneo compartilhado ainda não está implementado/i.test(p.textContent||''))p.textContent='Modo cooperativo R41: presença, chat, intenções, ações de missão e eventos de combate são sincronizados por sala. A resolução permanece por turnos e TERION continua autoritativo em cada ação.';});if(!o.roomId)return;const rr=r41Ensure().online,host=screen.querySelector('.online-room,.online-layout,.section-title')?.parentElement||screen;host.insertAdjacentHTML('beforeend',`<section class="card r41-online-actions"><span class="eyebrow">EQUIPE ONLINE • ESTADO COMPARTILHADO</span><h2>Ações sincronizadas</h2><p>Presença, chat e ações de gameplay da equipe são registradas no servidor da sala. O Mestre IA recebe as últimas intenções dos jogadores; cada resultado mecânico continua passando por TERION e pelo save da conta.</p><textarea id="r41-online-intent" rows="3" placeholder="Ex.: Eu cubro a saída enquanto Kakashi investiga o selo."></textarea><button class="btn" data-action="r41-online-intent">Enviar ação para a equipe</button><div class="travel-log">${(rr.actions||[]).slice(-12).reverse().map(x=>`<div><b>${esc(x.characterName||x.character_name||'Shinobi')}</b> • ${esc(x.action||'ação')}<br><small>${esc(x.payload?.text||JSON.stringify(x.payload||{}))}</small></div>`).join('')||'<div>Nenhuma ação compartilhada ainda.</div>'}</div></section>`);};
  function r41BroadcastGameplay(action,payload={}){const o=ensureOnlineState();if(!o.roomId||!accountToken())return;Promise.resolve(r41OnlineAction(action,payload)).then(()=>r41OnlineRefresh()).catch(e=>console.warn('R41 broadcast',e.message));}
  const aiGameContextR41Base=aiGameContext;aiGameContext=function(){const x=aiGameContextR41Base();const rr=r41Ensure().online,o=ensureOnlineState();x.onlineParty=o.roomId?{roomId:o.roomId,shared:rr.shared||{},recentActions:(rr.actions||[]).slice(-20).map(a=>({player:a.characterName||a.character_name,action:a.action,payload:a.payload,at:a.createdAt||a.created_at}))}:null;return x;};
  document.addEventListener('click',e=>{const b=e.target?.closest?.('[data-action="r41-online-intent"]');if(b){e.preventDefault();r41SendOnlineIntent();}});

  // ---------- COMBATE: TERION -> RESULTADO -> VISUAL -> HUD -> NARRATIVA -> SAVE ----------
  function r41CombatSnapshot(){const c=state.character,b=ui.battle,e=b?.enemy;return {playerHp:Number(c?.hp||0),playerChakra:Number(c?.chakra||0),kurai:Number(c?.kurai?.chakra||0),enemyHp:Number(e?.hp||0),enemyChakra:Number(e?.chakra||0),conditions:r41Clone(c?.conditions||[]),enemyConditions:r41Clone(e?.conditions||[]),turn:Number(b?.turn||0)};}
  function r41CombatVisual(result={},technique={}){if(!ui.battle)return;const events=window.SNSCombatPresentationEngine?.fromResult?.(result)||[],validation=window.SNSCombatPresentationEngine?.validate?.(result,events)||{ok:true,errors:[]},states=window.SNSVisualStateEngine?.fromCombatResult?.(result)||[],animation=window.SNSAnimationRegistry?.infer?.(technique)||null;ui.battle.r41Presentation={at:Date.now(),result:r41Clone(result),events:r41Clone(events),states:r41Clone(states),animation:r41Clone(animation),validation};r41Ensure().lastCombatPresentation=r41Clone(ui.battle.r41Presentation);
    const cls=result.defense==='block'?'block':result.defense==='dodge'?'dodge':Number(result.damage||0)>0?'hit':'miss',label=result.label||technique.name||'Ação TERION',detail=result.hit===false?'Falhou':result.defense?`Defesa: ${result.defense}`:`${Number(result.damage||0)} dano`;
    requestAnimationFrame(()=>{document.querySelectorAll('.r41-combat-present').forEach(x=>x.remove());const n=document.createElement('div');n.className=`r41-combat-present ${cls}`;n.innerHTML=`<b>${esc(label)}</b><small>${esc(detail)}</small>`;document.body.appendChild(n);const field=screen.querySelector('.v81-battlefield,.tactical-layout,.play-map');field?.classList.add('r41-combat-pulse');setTimeout(()=>field?.classList.remove('r41-combat-pulse'),520);setTimeout(()=>n.remove(),1100);});
    r41BroadcastGameplay('combat_result',{label,result,validation,technique:{id:technique?.id||'',name:technique?.name||''}});if(!validation.ok)console.error('[R41_COMBAT_GATE]',validation.errors,result);try{window.SNSSavePointManager?.record?.('combat_result',{result,validation});}catch{}try{v83SavePoint?.('Resultado de combate R41',[{result:r41Clone(result),validation:r41Clone(validation)}]);}catch{}saveState(true);
  }
  function r41PresentDiff(before,after,label,technique={},target='enemy'){
    if(!before||!after)return;const damage=target==='enemy'?Math.max(0,before.enemyHp-after.enemyHp):Math.max(0,before.playerHp-after.playerHp),hit=damage>0,spent=Math.max(0,before.playerChakra-after.playerChakra),conditions=target==='enemy'?after.enemyConditions:after.conditions;const result={actionType:technique?.class||technique?.type||'attack',label,hit,damage,conditions,resourceSpent:spent,ko:target==='enemy'?after.enemyHp<=0:after.playerHp<=0};r41CombatVisual(result,technique);
  }
  const basicAttackR41Base=basicAttack;basicAttack=function(){const before=r41CombatSnapshot(),out=basicAttackR41Base(),after=r41CombatSnapshot();r41PresentDiff(before,after,'Ataque básico',{name:'Ataque básico',type:'attack'},'enemy');return out;};
  const useBattleJutsuR41Base=useBattleJutsu;useBattleJutsu=function(id){const j=jutsuById(id),before=r41CombatSnapshot(),out=useBattleJutsuR41Base(id),after=r41CombatSnapshot();r41PresentDiff(before,after,j?.name||'Técnica',j||{},'enemy');return out;};
  const enemyTurnR41Base=enemyTurn;enemyTurn=function(){const before=r41CombatSnapshot(),out=enemyTurnR41Base(),after=r41CombatSnapshot();if(after.playerHp!==before.playerHp||JSON.stringify(after.conditions)!==JSON.stringify(before.conditions))r41PresentDiff(before,after,ui.battle?.enemy?.name||'Ação inimiga',{name:ui.battle?.enemy?.name||'Inimigo',type:'attack'},'player');return out;};
  const v8LeonBasicAttackR41Base=v8LeonBasicAttack;v8LeonBasicAttack=function(){const before=r41CombatSnapshot(),out=v8LeonBasicAttackR41Base(),after=r41CombatSnapshot();r41PresentDiff(before,after,'Kurai',{name:'Kurai',class:'kenjutsu'},'enemy');return out;};
  const v8LeonUseActionR41Base=v8LeonUseAction;v8LeonUseAction=function(id,choice={}){const a=v75Action(id)||{name:id},before=r41CombatSnapshot(),out=v8LeonUseActionR41Base(id,choice),after=r41CombatSnapshot(),changed=before.playerChakra!==after.playerChakra||before.kurai!==after.kurai||before.enemyHp!==after.enemyHp;if(changed){const tri=window.SNSTransformationStateEngine?.apply?.(state.character,a,{success:true,active:true,before,after});if(tri){r41Ensure().narrative.lastConfirmedFact=tri.narrativeFact;v83SavePoint?.('Transformação/Dōjutsu sincronizado',[tri]);saveState(true);}}r41PresentDiff(before,after,a.name||'Técnica',a,'enemy');return out;};
  const v8LeonEnemyTurnR41Base=v8LeonEnemyTurn;v8LeonEnemyTurn=function(){const before=r41CombatSnapshot(),out=v8LeonEnemyTurnR41Base(),after=r41CombatSnapshot();if(after.playerHp!==before.playerHp)r41PresentDiff(before,after,ui.battle?.enemy?.name||'Ação inimiga',{name:ui.battle?.enemy?.name||'Inimigo'},'player');return out;};

  // ---------- STATUS / DIAGNÓSTICO ----------
  const renderConfigR41Base=renderConfig;
  renderConfig=function(){renderConfigR41Base();const r=r41Ensure(),c=state.character;const box=document.createElement('section');box.className='card r41-diagnostics';box.innerHTML=`<span class="eyebrow">R41 • MD OPERACIONAL</span><h2>Gates ativos</h2><div class="list"><div class="list-row"><span>Autosave local</span><b>${r.autosave.localAt?'ATIVO':'AGUARDANDO'}</b></div><div class="list-row"><span>Autosave conta</span><b>${accountToken()?'ATIVO':'SEM SESSÃO'}</b></div><div class="list-row"><span>Ferimentos persistentes</span><b>${r41ActiveInjuries().length}</b></div><div class="list-row"><span>Minijogos concluídos</span><b>${r.minigames.total}</b></div><div class="list-row"><span>Kurai no HUD</span><b>${c?.privateCharacter==='leon'?'SIM':'N/A'}</b></div><div class="list-row"><span>Ações online sincronizadas</span><b>${r.online.actions?.length||0}</b></div></div><p class="muted">Missão sem gameplay, treino sem interação, imagem conhecida em fallback, combate contradizendo TERION ou save que perde estado são tratados como falha de gate.</p>`;screen.prepend(box);};

